function BenefitFormPanel({ employees, onClose, onSubmit }) {
  const [form, setForm] = useState({ employee: employees[0]?.name || "", type: BENEFIT_TYPES[0], monthlyValue: "" });
  function set(key, val) { setForm((f) => ({ ...f, [key]: val })); }
  function handleSubmit(e) { e.preventDefault(); if (!(Number(form.monthlyValue) > 0)) return; onSubmit(form); }

  return (
    <div className="fixed inset-0 z-30 flex justify-end">
      <div className="absolute inset-0 bg-[#111827]/20 backdrop-blur-[2px]" onClick={onClose} />
      <form onSubmit={handleSubmit} className="relative w-full sm:w-[380px] bg-white h-full rounded-l-[26px] border-l border-slate-200/80 shadow-2xl overflow-y-auto flex flex-col" style={{ animation: "slideIn .15s ease-out" }}>
        <div className="px-5 sm:px-6 pt-5 sm:pt-6 pb-4 sm:pb-5 border-b border-slate-100 bg-white/95 backdrop-blur sticky top-0 z-10 flex items-start justify-between">
          <div><p className="text-[11px] text-slate-400 uppercase tracking-wide">Benefits</p><h2 className="text-[18px] font-semibold text-[#111827] mt-0.5">Enroll Benefit</h2></div>
          <button type="button" onClick={onClose} className="text-slate-400 hover:text-slate-600" aria-label="Close"><X size={18} /></button>
        </div>
        <div className="px-5 sm:px-6 py-5 flex-1 space-y-4">
          <FormField label="Employee">
            <select className={inputClass} value={form.employee} onChange={(e) => set("employee", e.target.value)}>
              {employees.map((e) => <option key={e.id} value={e.name}>{e.name}</option>)}
            </select>
          </FormField>
          <FormField label="Benefit type">
            <select className={inputClass} value={form.type} onChange={(e) => set("type", e.target.value)}>
              {BENEFIT_TYPES.map((t) => <option key={t} value={t}>{t}</option>)}
            </select>
          </FormField>
          <FormField label="Monthly value (TZS 000)" required>
            <input type="number" min="0" className={inputClass} value={form.monthlyValue} onChange={(e) => set("monthlyValue", e.target.value)} placeholder="0" />
          </FormField>
        </div>
        <div className="px-5 sm:px-6 py-4 border-t border-slate-100 bg-white/95 backdrop-blur sticky bottom-0 z-10 flex gap-2">
          <button type="button" onClick={onClose} className="flex-1 text-[12px] font-medium border border-slate-200 rounded-lg py-2.5 hover:bg-slate-50">Cancel</button>
          <button type="submit" className="flex-1 text-[12px] font-medium btn-primary text-white rounded-lg py-2.5">Enroll</button>
        </div>
      </form>
    </div>
  );
}

/* ----------------------------------- PAYROLL ------------------------------------- */

function Payroll({ employees, expensesHook }) {
  const runs = useCompanyTable("hr_payroll_runs", payrollRunsSeed, { order: { col: "processed_date", ascending: false }, mapRow: mapPayrollRunRow });
  const { rows, setRows, loading } = runs;
  const activeEmployees = employees.filter((e) => e.status !== "Inactive");
  const currentTotal = activeEmployees.reduce((s, e) => s + e.salary, 0);
  const currentPeriod = TODAY.toLocaleDateString("en-US", { month: "long", year: "numeric" });
  const alreadyProcessed = rows.some((r) => r.period === currentPeriod);

  // Generate real payslips — one PDF-print page per employee, showing their
  // gross salary, real TRA PAYE (the same tested bracket function Tax Center
  // uses), net pay, and the company details. printAsPDF opens the browser's
  // print dialog which on every modern device gives "Save as PDF" as a
  // first-class option. Each payslip is a separate window so they can be
  // printed or saved individually or all at once.
  function generatePayslips(run, emps) {
    const co   = window.__smartManagerCompany || {};
    const ACCENT = "#16A34A";
    const DARK   = "#0D2214";
    // TRA PAYE brackets (TZS thousands / month)
    const PAYE = (s) => s <= 270 ? 0 : s <= 520 ? (s-270)*0.08 : s <= 760 ? 20+(s-520)*0.20 : s <= 1000 ? 68+(s-760)*0.25 : 128+(s-1000)*0.30;
    if (!emps.length) { notify("No active employees to generate payslips for.", "error"); return; }
    const rows = emps.map((e) => {
      const gross = e.salary;
      const paye  = Math.round(PAYE(gross) * 100) / 100;
      const sdl   = Math.round(gross * 0.035 * 100) / 100;
      const nhif  = Math.round(Math.min(gross * 0.015, 10) * 100) / 100; // NHIF 1.5% capped at 10k
      const totalDeductions = paye + sdl + nhif;
      const net   = gross - totalDeductions;
      return { ...e, gross, paye, sdl, nhif, totalDeductions, net };
    });

    const logoHtml = co.logo
      ? `<img src="${co.logo}" style="height:44px;object-fit:contain" alt="logo"/>`
      : `<div style="width:44px;height:44px;border-radius:10px;background:${ACCENT};display:flex;align-items:center;justify-content:center;font-size:22px;font-weight:900;color:#fff">${(co.name||"B").charAt(0)}</div>`;

    const slips = rows.map((e, idx) => `
      <div class="slip" style="page-break-after:${idx < rows.length-1 ? "always" : "auto"}">

        <!-- Header bar -->
        <div class="slip-header">
          <div style="display:flex;align-items:center;gap:14px">
            ${logoHtml}
            <div>
              <div style="font-size:17px;font-weight:800;color:white">${co.name || "BusinessSphere"}</div>
              <div style="font-size:10.5px;color:rgba(255,255,255,0.55);margin-top:2px">
                ${[co.address,co.city,"Tanzania"].filter(Boolean).join(" · ")}
                ${co.tin ? " · TIN: "+co.tin : ""}
              </div>
            </div>
          </div>
          <div style="text-align:right">
            <div style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.12em;color:rgba(255,255,255,0.5)">Payslip</div>
            <div style="font-size:22px;font-weight:900;color:${ACCENT};margin-top:2px">${run.period}</div>
            <div style="font-size:10.5px;color:rgba(255,255,255,0.4);margin-top:2px">Processed: ${run.processedDate}</div>
          </div>
        </div>

        <!-- Employee info band -->
        <div class="emp-band">
          <div>
            <div class="emp-name">${e.name || e.fullName}</div>
            <div class="emp-meta">${e.role || "Employee"}${e.department ? " · " + e.department : ""}${e.id ? " · ID: "+e.id : ""}</div>
          </div>
          <div style="text-align:right">
            <div style="font-size:10px;color:#9CA3AF;text-transform:uppercase;letter-spacing:.08em">Employee Since</div>
            <div style="font-size:12.5px;font-weight:600;color:#374151">${e.startDate || "—"}</div>
          </div>
        </div>

        <!-- Earnings + Deductions -->
        <div class="two-col">
          <!-- Earnings -->
          <div class="section">
            <div class="section-title" style="color:${ACCENT}">EARNINGS</div>
            <table class="line-table">
              <tr><td>Basic Salary</td><td class="amt green">TZS ${money(e.gross)}k</td></tr>
              <tr class="total-row"><td>GROSS PAY</td><td class="amt" style="font-size:14px;color:${ACCENT}">TZS ${money(e.gross)}k</td></tr>
            </table>
          </div>
          <!-- Deductions -->
          <div class="section">
            <div class="section-title" style="color:#EF4444">DEDUCTIONS</div>
            <table class="line-table">
              <tr><td>PAYE <span class="sub-note">(TRA brackets)</span></td><td class="amt red">− TZS ${money(e.paye)}k</td></tr>
              <tr><td>SDL <span class="sub-note">(3.5% of gross)</span></td><td class="amt red">− TZS ${money(e.sdl)}k</td></tr>
              <tr><td>NHIF <span class="sub-note">(1.5%, max 10k)</span></td><td class="amt red">− TZS ${money(e.nhif)}k</td></tr>
              <tr class="total-row"><td>TOTAL DEDUCTIONS</td><td class="amt red">− TZS ${money(e.totalDeductions)}k</td></tr>
            </table>
          </div>
        </div>

        <!-- Net pay banner -->
        <div class="net-banner">
          <div>
            <div style="font-size:10.5px;font-weight:700;text-transform:uppercase;letter-spacing:.1em;color:rgba(255,255,255,0.6)">NET PAY</div>
            <div style="font-size:10px;color:rgba(255,255,255,0.4);margin-top:2px">After all deductions</div>
          </div>
          <div style="text-align:right">
            <div style="font-size:30px;font-weight:900;color:white;letter-spacing:-0.5px">TZS ${money(e.net)}k</div>
            <div style="font-size:10px;color:rgba(255,255,255,0.5);margin-top:1px">Per month · ${run.period}</div>
          </div>
        </div>

        <!-- Payment info -->
        ${co.bankName ? `
        <div class="pay-info">
          <div class="pay-field"><div class="pay-label">Payment Method</div><div class="pay-value">Bank Transfer</div></div>
          ${co.bankName ? `<div class="pay-field"><div class="pay-label">Bank</div><div class="pay-value">${co.bankName}</div></div>` : ""}
          ${co.bankAccount ? `<div class="pay-field"><div class="pay-label">Account</div><div class="pay-value" style="font-family:monospace">${co.bankAccount}</div></div>` : ""}
        </div>` : ""}

        <!-- Footer note -->
        <div class="slip-footer">
          <span>Confidential — For employee use only</span>
          <span>Generated by BusinessSphere ERP · ${new Date().toLocaleDateString()}</span>
        </div>
      </div>
    `).join("");

    const win = window.open("","_blank","width=900,height=1100");
    if (!win) { notify("Pop-up blocked — allow pop-ups to print payslips.", "error"); return; }
    win.document.write(`<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"/>
      <title>Payslips — ${run.period}</title>
      <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet"/>
      <style>
        *{box-sizing:border-box;margin:0;padding:0}
        body{font-family:Inter,Arial,sans-serif;background:#F3F4F6;-webkit-print-color-adjust:exact;print-color-adjust:exact}
        @media print{body{background:white}.toolbar{display:none!important}}
        .slip{max-width:720px;margin:24px auto;background:white;border-radius:14px;overflow:hidden;box-shadow:0 4px 32px rgba(0,0,0,.10)}
        .slip-header{background:${DARK};padding:28px 32px;display:flex;justify-content:space-between;align-items:flex-start}
        .emp-band{background:#F8FAFB;border-bottom:1px solid #E5E7EB;padding:18px 32px;display:flex;justify-content:space-between;align-items:center}
        .emp-name{font-size:18px;font-weight:800;color:#111827}
        .emp-meta{font-size:11px;color:#6B7280;margin-top:3px}
        .two-col{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:#E5E7EB;margin:0}
        .section{background:white;padding:20px 24px}
        .section-title{font-size:10px;font-weight:800;text-transform:uppercase;letter-spacing:.12em;margin-bottom:10px}
        .line-table{width:100%;border-collapse:collapse}
        .line-table tr{border-bottom:1px solid #F9FAFB}
        .line-table td{padding:6px 0;font-size:12.5px;color:#374151}
        .amt{text-align:right;font-family:monospace;font-weight:600}
        .green{color:#16A34A}.red{color:#EF4444}
        .sub-note{font-size:10px;color:#9CA3AF;font-weight:400}
        .total-row td{border-top:2px solid #E5E7EB;padding-top:10px;font-weight:700;font-size:13px;border-bottom:none}
        .net-banner{background:${DARK};padding:22px 32px;display:flex;justify-content:space-between;align-items:center}
        .pay-info{padding:14px 32px;background:#F0FDF4;border-top:1px solid #D1FAE5;display:flex;gap:32px;flex-wrap:wrap}
        .pay-field{}.pay-label{font-size:10px;color:#9CA3AF;margin-bottom:2px}.pay-value{font-size:12.5px;font-weight:600;color:#111827}
        .slip-footer{padding:12px 32px;background:#F8FAFB;border-top:1px solid #E5E7EB;display:flex;justify-content:space-between;font-size:10px;color:#9CA3AF}
        .toolbar{position:fixed;bottom:24px;right:24px;display:flex;gap:8px;z-index:99}
        .btn{padding:10px 20px;border-radius:10px;font-weight:700;font-size:13px;cursor:pointer;border:none;font-family:Inter,sans-serif}
        .btn-p{background:${ACCENT};color:white}.btn-c{background:white;color:#111827;border:1.5px solid #E5E7EB}
      </style></head><body>
      ${slips}
      <div class="toolbar no-print">
        <button class="btn btn-c" onclick="window.close()">Close</button>
        <button class="btn btn-p" onclick="window.print()">Print / Save PDF</button>
      </div>
    </body></html>`);
    win.document.close();
    setTimeout(() => win.focus(), 200);
    notify(`${rows.length} payslip${rows.length !== 1 ? "s" : ""} ready — print or save as PDF.`);
  }

  async function processPayroll() {
    const draft = {
      id: `PR-${TODAY.getFullYear()}-${String(TODAY.getMonth() + 1).padStart(2, "0")}`,
      period: currentPeriod, employeeCount: activeEmployees.length, totalAmount: currentTotal,
      status: "Processed", processedDate: TODAY.toISOString().slice(0, 10),
    };
    setRows((prev) => [draft, ...prev]);
    notify(`Payroll processed for ${currentPeriod} — TZS ${money(currentTotal)}k`);

    // The real consequence: processing payroll creates an actual expense in
    // the shared Finance table, the same one every other module reads —
    // not a number that only exists inside HR.
    const expenseDraft = {
      id: docId("EX"),
      vendor: `Payroll — ${currentPeriod}`, category: "Salaries",
      date: draft.processedDate, dueDate: draft.processedDate,
      amount: currentTotal, status: "Paid", method: "Bank Transfer",
    };
    expensesHook.setRows((prev) => [expenseDraft, ...prev]);

    if (IS_CONFIGURED) {
      try {
        const header = await sb("hr_payroll_runs").insert({
          period: draft.period, employee_count: draft.employeeCount, total_amount: draft.totalAmount,
          status: "Processed", processed_date: draft.processedDate,
        }).single().run();
        if (header?.id) setRows((prev) => prev.map((r) => (r.id === draft.id ? { ...r, dbId: header.id } : r)));
        const expHeader = await sb("finance_expenses").insert({
          vendor: expenseDraft.vendor, category: "Salaries", expense_date: expenseDraft.date,
          due_date: expenseDraft.dueDate, amount: expenseDraft.amount, status: "Paid", method: "Bank Transfer",
        }).single().run();
        if (expHeader?.id) expensesHook.setRows((prev) => prev.map((e) => (e.id === expenseDraft.id ? { ...e, dbId: expHeader.id } : e)));
      } catch (_e) { notify("Payroll processed locally, but saving to the server failed.", "error"); }
    }
  }

  return (
    <div className="space-y-5">
      <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-5 sm:p-6">
        <div className="flex items-center justify-between mb-4">
          <div>
            <h3 className="text-[14px] font-semibold text-[#111827]">Current Period — {currentPeriod}</h3>
            <p className="text-[12px] text-slate-400">{activeEmployees.length} active employees</p>
          </div>
          <p className="text-[20px] font-mono font-semibold text-[#111827]">TZS {money(currentTotal)}k</p>
        </div>
        <button
          onClick={processPayroll}
          disabled={alreadyProcessed || activeEmployees.length === 0}
          className="btn-primary text-white text-[13px] font-semibold rounded-lg py-3 w-full disabled:opacity-40 disabled:cursor-not-allowed"
        >
          {alreadyProcessed ? `${currentPeriod} already processed` : `Process Payroll — TZS ${money(currentTotal)}k`}
        </button>
        {!alreadyProcessed && (
          <p className="text-[11.5px] text-slate-400 mt-2.5">Creates a real "Salaries" expense in Finance for the total shown above.</p>
        )}
      </div>

      {/* Payroll analytics */}
      {activeEmployees.length > 0 && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4">
            <h3 className="text-[14px] font-semibold text-[#111827] mb-3">Payroll by Department</h3>
            {(() => {
              const dm = {};
              activeEmployees.forEach(e=>{ const d=e.department||"General"; dm[d]=(dm[d]||0)+e.salary; });
              const data=Object.entries(dm).sort((a,b)=>b[1]-a[1]).map(([name,value])=>({name,value}));
              return(
                <ResponsiveContainer width="100%" height={160}>
                  <BarChart data={data} layout="vertical" margin={{left:5,right:20,top:0,bottom:0}}>
                    <XAxis type="number" tick={{fontSize:10}} axisLine={false} tickLine={false}/>
                    <YAxis dataKey="name" type="category" tick={{fontSize:11}} axisLine={false} tickLine={false} width={75}/>
                    <Tooltip formatter={v=>["TZS "+money(v)+"k","Payroll"]}/>
                    <Bar dataKey="value" fill="#16A34A" radius={[0,5,5,0]}/>
                  </BarChart>
                </ResponsiveContainer>
              );
            })()}
          </div>
          <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4">
            <h3 className="text-[14px] font-semibold text-[#111827] mb-3">Employee Salary Breakdown</h3>
            <div className="space-y-2 overflow-y-auto max-h-[165px] pr-1">
              {activeEmployees.slice(0,8).map(e=>{
                const pct=currentTotal>0?e.salary/currentTotal*100:0;
                return(
                  <div key={e.id} className="flex items-center gap-2">
                    <div className="w-6 h-6 rounded-full bg-[#16A34A] flex items-center justify-center text-white text-[9px] font-bold shrink-0">{(e.fullName||e.name||"?").charAt(0)}</div>
                    <div className="flex-1 min-w-0">
                      <div className="flex justify-between items-center mb-0.5">
                        <span className="text-[12px] font-medium text-[#111827] truncate">{e.fullName||e.name}</span>
                        <span className="text-[11px] font-mono font-bold text-[#16A34A] shrink-0 ml-2">TZS {money(e.salary)}k</span>
                      </div>
                      <div className="w-full h-1.5 bg-slate-100 rounded-full overflow-hidden">
                        <div className="h-full bg-[#16A34A] rounded-full" style={{width:pct+"%"}}/>
                      </div>
                    </div>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      )}

            <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-[13px] min-w-[560px]">
            <thead><tr className="border-b border-slate-100 text-left text-[11px] text-slate-400 uppercase tracking-wide">
              <th className="px-4 py-3 font-medium">Period</th><th className="px-4 py-3 font-medium text-right">Employees</th><th className="px-4 py-3 font-medium text-right">Total (TZS 000)</th><th className="px-4 py-3 font-medium">Processed</th><th className="px-4 py-3 font-medium">Export</th>
            </tr></thead>
            <tbody>
              {loading && <SkeletonRows cols={4} />}
              {!loading && rows.map((r) => (
                <tr key={r.id} className="border-b border-slate-50 last:border-0">
                  <td className="px-4 py-3 font-medium text-[#111827]">{r.period}</td>
                  <td className="px-4 py-3 text-right font-mono text-slate-500">{r.employeeCount}</td>
                  <td className="px-4 py-3 text-right font-mono">{money(r.totalAmount)}</td>
                  <td className="px-4 py-3 text-slate-500 font-mono">{r.processedDate}</td>
                  <td className="px-4 py-3">
                    <div className="flex gap-2 items-center">
                      <button onClick={() => generatePayslips(r, activeEmployees)} className="text-[11.5px] font-medium text-[#16A34A] hover:underline flex items-center gap-1"><Download size={11}/> PDF</button>
                      <button onClick={()=>downloadCSV(`payroll-${r.period}`,activeEmployees.map(e=>{
                        const gross=e.salary||0;
                        const PAYE=(s)=>s<=270?0:s<=520?(s-270)*0.08:s<=760?20+(s-520)*0.20:s<=1000?68+(s-760)*0.25:128+(s-1000)*0.30;
                        const nssf=Math.min(gross*0.10,20);const nhif=gross<100?0.015*gross:gross<149?0.02*gross:0.025*gross;
                        const paye=PAYE(gross);const net=gross-paye-nssf-nhif;
                        return {Name:e.name||e.full_name||"",Dept:e.dept||"",Gross_k:gross,PAYE_k:Math.round(paye),NSSF_k:Math.round(nssf),NHIF_k:Math.round(nhif),Net_k:Math.round(net)};
                      }),[{key:"Name",label:"Employee"},{key:"Dept",label:"Department"},{key:"Gross_k",label:"Gross (TZS k)"},{key:"PAYE_k",label:"PAYE"},{key:"NSSF_k",label:"NSSF"},{key:"NHIF_k",label:"NHIF"},{key:"Net_k",label:"Net Pay"}])}
                        className="text-[11.5px] font-medium text-[#2563EB] hover:underline flex items-center gap-1"><Download size={11}/> CSV</button>
                    </div>
                  </td>
                </tr>
              ))}
              {!loading && rows.length === 0 && <tr><td colSpan={4}><EmptyState icon={Banknote} title="No payroll runs yet" hint="Processed payroll periods will appear here." /></td></tr>}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

/* ------------------------------- MANUFACTURING --------------------------------- */

const MFG_TABS = [
  { id: "boms", label: "Bill of Materials", icon: ClipboardList },
  { id: "workorders", label: "Production Planning", icon: Factory },
  { id: "machines", label: "Machines", icon: Cog },
  { id: "quality", label: "Quality Control", icon: ShieldCheck },
  { id: "maintenance", label: "Maintenance", icon: Wrench },
];

function bomUnitCost(bom, inventoryRows) {
  const materials = bom.components.reduce((s, c) => s + bomComponentCost(c.sku, inventoryRows) * c.qty, 0);
  return materials + bom.laborCost;
}

function Manufacturing({ inventory, workOrdersHook, expensesHook }) {
  const [tab, setTab] = useState("workorders");
  const { rows: workOrders, setRows: setWorkOrders, loading, error } = workOrdersHook;
  const boms = useCompanyTable("manufacturing_boms", bomsSeed, {
    select: "*,manufacturing_bom_components(*)", order: { col: "product_name", ascending: true }, mapRow: mapBomRow,
  });

  const stats = useMemo(() => {
    const inProgress = workOrders.filter((w) => w.status === "In Progress").length;
    const planned = workOrders.filter((w) => w.status === "Planned").length;
    const completedThisMonth = workOrders.filter((w) => w.status === "Completed").length;
    const wipValue = workOrders
      .filter((w) => w.status !== "Cancelled")
      .reduce((s, w) => {
        const bom = boms.rows.find((b) => b.id === w.bomId);
        return s + (bom ? bomUnitCost(bom, inventory.rows) * w.qty : 0);
      }, 0);
    return { inProgress, planned, completedThisMonth, wipValue };
  }, [workOrders, boms.rows, inventory.rows]);

  const MFG_KPIS = [
    { label: "In Progress", value: String(stats.inProgress), delta: "Work orders", up: true, icon: Factory },
    { label: "Planned", value: String(stats.planned), delta: "Queued", up: false, icon: ClipboardList },
    { label: "Completed", value: String(stats.completedThisMonth), delta: "All time", up: true, icon: CheckCircle2 },
    { label: "WIP Value", value: `TZS ${money(Math.round(stats.wipValue))}k`, delta: "Active orders", up: true, icon: CircleDollarSign },
  ];

  return (
    <div className="space-y-5">
      {IS_CONFIGURED && error && (
        <div className="bg-[#EF4444]/5 border border-[#EF4444]/20 text-[#EF4444] text-[12.5px] rounded-lg px-3.5 py-2.5">
          {"Could not reach Supabase — check your connection."}
        </div>
      )}
      <div>
        <h1 className="text-[20px] sm:text-[22px] font-semibold text-[#111827] tracking-tight">Manufacturing</h1>
        <p className="text-[13px] text-slate-500 mt-1">Bills of materials and production work orders</p>
      </div>

      <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1 overflow-x-auto w-fit max-w-full">
        {MFG_TABS.map((t) => {
          const Icon = t.icon;
          const isActive = tab === t.id;
          return (
            <button
              key={t.id}
              onClick={() => setTab(t.id)}
              className={`text-[12px] font-medium px-3 py-1.5 rounded-md flex items-center gap-1.5 whitespace-nowrap transition-colors ${
                isActive ? "bg-white text-[#111827] shadow-sm" : "text-slate-500 hover:text-slate-700"
              }`}
            >
              <Icon size={13} /> {t.label}
            </button>
          );
        })}
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
        {MFG_KPIS.map((k) => <KpiCard key={k.label} item={k} />)}
      </div>

      {/* Work Order Status Chart */}
      {tab === "workorders" && workOrders.length > 0 && (() => {
        const woStatusData = ["Planned","In Progress","Completed","Cancelled","On Hold"].map((s,i)=>({
          name:s, value:workOrders.filter(w=>w.status===s).length,
          fill:["#F59E0B","#2563EB","#16A34A","#EF4444","#94A3B8"][i],
        })).filter(d=>d.value>0);
        const woByCat = Object.entries(
          workOrders.reduce((m,w)=>{const bom=boms.rows.find(b=>b.id===w.bomId);const cat=bom?.product_name||w.productName||"Unknown";m[cat]=(m[cat]||0)+1;return m;},{})
        ).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([name,value],i)=>({
          name:name.length>14?name.slice(0,12)+"…":name,
          value,
          fill:["#2563EB","#16A34A","#D97706","#7C3AED","#EF4444"][i],
        }));
        return (
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
            <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4">
              <h3 className="text-[13.5px] font-semibold text-[#111827] mb-3">Work Order Status</h3>
              <div className="flex items-center gap-4">
                <ResponsiveContainer width="55%" height={150}>
                  <RPieChart><Pie data={woStatusData} dataKey="value" cx="50%" cy="50%" outerRadius={60} innerRadius={30}>
                    {woStatusData.map((d,i)=><Cell key={i} fill={d.fill}/>)}
                  </Pie><Tooltip formatter={(v,n)=>[v+" orders",n]}/></RPieChart>
                </ResponsiveContainer>
                <div className="flex-1 space-y-1.5">
                  {woStatusData.map(d=>(
                    <div key={d.name} className="flex items-center justify-between">
                      <span className="flex items-center gap-1.5 text-[12px]"><span className="w-2.5 h-2.5 rounded-full" style={{background:d.fill}}/>{d.name}</span>
                      <span className="text-[13px] font-bold" style={{color:d.fill}}>{d.value}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>
            <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4">
              <h3 className="text-[13.5px] font-semibold text-[#111827] mb-3">Top Products in Production</h3>
              {woByCat.length===0?<p className="text-slate-400 text-center py-6">No data</p>:(
                <ResponsiveContainer width="100%" height={150}>
                  <BarChart data={woByCat} layout="vertical" margin={{left:5,right:20,top:0,bottom:0}}>
                    <CartesianGrid vertical={false} stroke="#EEF1F4"/>
                    <XAxis type="number" tick={{fontSize:9}} axisLine={false} tickLine={false}/>
                    <YAxis dataKey="name" type="category" tick={{fontSize:10}} axisLine={false} tickLine={false} width={80}/>
                    <Tooltip formatter={(v)=>[v+" orders","Work Orders"]}/>
                    <Bar dataKey="value" radius={[0,4,4,0]} maxBarSize={16}>
                      {woByCat.map((d,i)=><Cell key={i} fill={d.fill}/>)}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              )}
            </div>
          </div>
        );
      })()}

      {tab === "boms" && <BOMs boms={boms} inventory={inventory} />}
      {tab === "workorders" && <WorkOrders workOrders={workOrders} setWorkOrders={setWorkOrders} inventory={inventory} boms={boms} loading={loading} />}
      {tab === "machines" && <Machines />}
      {tab === "quality" && <QualityControl workOrders={workOrders} />}
      {tab === "maintenance" && <Maintenance expensesHook={expensesHook} />}
    </div>
  );
}

function BOMs({ boms, inventory }) {
  const { rows, setRows, loading } = boms;
  const [selected, setSelected] = useState(null);
  const [showForm, setShowForm] = useState(false);

  async function addBom(form) {
    const draft = {
      id: docId("BOM"),
      product: form.product, outputUnit: form.outputUnit || "unit",
      laborCost: Number(form.laborCost) || 0, components: form.components,
    };
    setRows((prev) => [draft, ...prev]);
    setShowForm(false);
    notify(`BOM created: ${draft.product}`);
    if (IS_CONFIGURED) {
      try {
        const header = await sb("manufacturing_boms").insert({
          product_name: draft.product, output_unit: draft.outputUnit, labor_cost: draft.laborCost,
        }).single().run();
        if (header?.id) {
          await sb("manufacturing_bom_components").insert(
            draft.components.map((c) => ({ bom_id: header.id, item_sku: c.sku, qty: c.qty }))
          ).run();
          setRows((prev) => prev.map((b) => (b.id === draft.id ? { ...b, dbId: header.id } : b)));
        }
      } catch (_e) { notify("BOM created locally, but saving to the server failed.", "error"); }
    }
  }

  async function deleteBom(id) {
    const b = rows.find((x) => x.id === id);
    setRows((prev) => prev.filter((x) => x.id !== id));
    setSelected(null);
    if (IS_CONFIGURED && b?.dbId) {
      try { await sb("manufacturing_boms").eq("id", b.dbId).delete().run(); } catch (_e) { notify("Couldn't delete the BOM on the server.", "error"); }
    }
  }

  return (
    <div className="space-y-5">
      <div className="flex justify-end">
        <button onClick={() => setShowForm(true)} className="btn-primary text-white text-[13px] font-medium px-3.5 py-2 rounded-lg flex items-center gap-1.5 shadow-sm">
          <Plus size={15} /> New BOM
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
        {loading && Array.from({ length: 3 }).map((_, i) => <div key={i} className="bg-white rounded-xl border border-slate-200/80 h-28 skeleton-shimmer" />)}
        {!loading && rows.map((bom) => (
          <button
            key={bom.id}
            onClick={() => setSelected(bom)}
            className="text-left bg-white rounded-xl border border-slate-200/80 shadow-sm p-4 hover:border-[#16A34A]/50 hover:shadow-md transition-all"
          >
            <p className="text-[11px] font-mono text-slate-400">{bom.id}</p>
            <p className="text-[14px] font-semibold text-[#111827] mt-0.5 mb-3">{bom.product}</p>
            <div className="flex items-center justify-between text-[12px] text-slate-500">
              <span>{bom.components.length} components</span>
              <span className="font-mono font-medium text-[#111827]">TZS {money(bomUnitCost(bom, inventory.rows))}k / {bom.outputUnit}</span>
            </div>
          </button>
        ))}
        {!loading && rows.length === 0 && (
          <div className="col-span-full bg-white rounded-xl border border-slate-200/80 shadow-sm">
            <EmptyState icon={ClipboardList} title="No BOMs yet" hint="Define what goes into a manufactured product so work orders can check material sufficiency and cost it accurately." actionLabel="New BOM" onAction={() => setShowForm(true)} />
          </div>
        )}
      </div>

      {selected && <BOMPanel bom={selected} inventory={inventory} onClose={() => setSelected(null)} onDelete={deleteBom} />}
      {showForm && <BOMFormPanel inventory={inventory} onClose={() => setShowForm(false)} onSubmit={addBom} />}
    </div>
  );
}

function BOMPanel({ bom, inventory, onClose, onDelete }) {
  const materialsCost = bom.components.reduce((s, c) => s + bomComponentCost(c.sku, inventory.rows) * c.qty, 0);
  const totalCost = materialsCost + bom.laborCost;

  return (
    <div className="fixed inset-0 z-30 flex justify-end">
      <div className="absolute inset-0 bg-[#111827]/20 backdrop-blur-[2px]" onClick={onClose} />
      <div className="relative w-full sm:w-[420px] bg-white h-full rounded-l-[26px] border-l border-slate-200/80 shadow-2xl overflow-y-auto flex flex-col" style={{ animation: "slideIn .15s ease-out" }}>
        <div className="px-6 pt-6 pb-5 border-b border-slate-100">
          <div className="flex items-start justify-between">
            <div>
              <p className="text-[11px] font-mono text-slate-400">{bom.id}</p>
              <h2 className="text-[17px] font-semibold text-[#111827] mt-0.5">{bom.product}</h2>
            </div>
            <button onClick={onClose} className="text-slate-400 hover:text-slate-600 shrink-0" aria-label="Close"><X size={18} /></button>
          </div>
        </div>

        <div className="px-6 py-5 flex-1">
          <p className="text-[11px] text-slate-400 mb-2 uppercase tracking-wide">Components (per {bom.outputUnit})</p>
          <div className="border border-slate-100 rounded-lg overflow-hidden mb-5">
            {bom.components.map((c, i) => {
              const item = inventory.rows.find((it) => it.sku === c.sku);
              return (
                <div key={i} className={`flex items-center justify-between px-3 py-2.5 text-[13px] ${i !== bom.components.length - 1 ? "border-b border-slate-50" : ""}`}>
                  <div className="min-w-0 pr-2">
                    <p className="text-slate-700 truncate">{item?.name || c.sku}</p>
                    <p className="text-[11px] text-slate-400 font-mono">{c.qty} × TZS {money(bomComponentCost(c.sku, inventory.rows))}k</p>
                  </div>
                  <span className="font-mono text-[#111827] shrink-0">{money(c.qty * bomComponentCost(c.sku, inventory.rows))}k</span>
                </div>
              );
            })}
          </div>

          <div className="space-y-1.5 text-[13px]">
            <div className="flex justify-between text-slate-500"><span>Materials</span><span className="font-mono">TZS {money(materialsCost)}k</span></div>
            <div className="flex justify-between text-slate-500"><span>Labor</span><span className="font-mono">TZS {money(bom.laborCost)}k</span></div>
            <div className="flex justify-between text-[#111827] font-semibold text-[14px] pt-1.5 border-t border-slate-100 mt-1.5">
              <span>Cost per {bom.outputUnit}</span><span className="font-mono">TZS {money(totalCost)}k</span>
            </div>
          </div>

          <div className="flex-1" />
        </div>
        <div className="px-6 py-4 border-t border-slate-100">
          <ConfirmDeleteButton label="Delete BOM" onConfirm={() => onDelete(bom.id)} />
        </div>
      </div>
    </div>
  );
}

function BOMFormPanel({ inventory, onClose, onSubmit }) {
  const [product, setProduct] = useState("");
  const [outputUnit, setOutputUnit] = useState("unit");
  const [laborCost, setLaborCost] = useState("");
  const [components, setComponents] = useState([{ sku: inventory.rows[0]?.sku || "", qty: "" }]);

  function updateComponent(i, key, val) {
    setComponents((prev) => prev.map((c, idx) => (idx === i ? { ...c, [key]: val } : c)));
  }
  function addComponent() { setComponents((prev) => [...prev, { sku: inventory.rows[0]?.sku || "", qty: "" }]); }
  function removeComponent(i) { setComponents((prev) => prev.filter((_, idx) => idx !== i)); }

  const validComponents = components.filter((c) => c.sku && Number(c.qty) > 0).map((c) => ({ sku: c.sku, qty: Number(c.qty) }));
  const materialsCost = validComponents.reduce((s, c) => s + bomComponentCost(c.sku, inventory.rows) * c.qty, 0);
  const totalCost = materialsCost + (Number(laborCost) || 0);
  const valid = product.trim() && validComponents.length > 0;

  function handleSubmit(e) {
    e.preventDefault();
    if (!valid) return;
    onSubmit({ product, outputUnit, laborCost, components: validComponents });
  }

  return (
    <div className="fixed inset-0 z-30 flex justify-end">
      <div className="absolute inset-0 bg-[#111827]/20 backdrop-blur-[2px]" onClick={onClose} />
      <form onSubmit={handleSubmit} className="relative w-full sm:w-[440px] bg-white h-full rounded-l-[26px] border-l border-slate-200/80 shadow-2xl overflow-y-auto flex flex-col" style={{ animation: "slideIn .15s ease-out" }}>
        <div className="px-5 sm:px-6 pt-5 sm:pt-6 pb-4 sm:pb-5 border-b border-slate-100 bg-white/95 backdrop-blur sticky top-0 z-10 flex items-start justify-between">
          <div><p className="text-[11px] text-slate-400 uppercase tracking-wide">Manufacturing</p><h2 className="text-[18px] font-semibold text-[#111827] mt-0.5">New Bill of Materials</h2></div>
          <button type="button" onClick={onClose} className="text-slate-400 hover:text-slate-600" aria-label="Close"><X size={18} /></button>
        </div>
        <div className="px-5 sm:px-6 py-5 flex-1 space-y-4">
          <FormField label="Product name" required>
            <input className={inputClass} value={product} onChange={(e) => setProduct(e.target.value)} placeholder="e.g. Cold Chain Storage Unit" />
          </FormField>
          <div className="grid grid-cols-2 gap-3">
            <FormField label="Output unit"><input className={inputClass} value={outputUnit} onChange={(e) => setOutputUnit(e.target.value)} placeholder="unit" /></FormField>
            <FormField label="Labor cost (TZS 000)"><input type="number" min="0" className={inputClass} value={laborCost} onChange={(e) => setLaborCost(e.target.value)} placeholder="0" /></FormField>
          </div>

          <div>
            <p className="text-[11px] font-medium text-slate-500 mb-2">Components</p>
            <div className="space-y-2.5">
              {components.map((c, i) => (
                <div key={i} className="flex gap-2 items-start">
                  <select className={`${inputClass} flex-1`} value={c.sku} onChange={(e) => updateComponent(i, "sku", e.target.value)}>
                    {inventory.rows.map((it) => <option key={it.sku} value={it.sku}>{it.name}</option>)}
                  </select>
                  <input type="number" min="0" className={`${inputClass} w-20`} value={c.qty} onChange={(e) => updateComponent(i, "qty", e.target.value)} placeholder="Qty" />
                  {components.length > 1 && (
                    <button type="button" onClick={() => removeComponent(i)} className="text-slate-300 hover:text-[#EF4444] mt-2.5 shrink-0" aria-label={`Remove component ${i + 1}`}><X size={14} /></button>
                  )}
                </div>
              ))}
            </div>
            <button type="button" onClick={addComponent} className="text-[12px] font-medium text-[#16A34A] hover:text-[#15803D] mt-2 flex items-center gap-1"><Plus size={12} /> Add component</button>
          </div>

          {validComponents.length > 0 && (
            <div className="bg-slate-50 rounded-lg p-3 text-[13px] space-y-1">
              <div className="flex justify-between text-slate-500"><span>Materials</span><span className="font-mono">TZS {money(Math.round(materialsCost))}k</span></div>
              <div className="flex justify-between font-semibold text-[#111827] pt-1 border-t border-slate-200"><span>Cost per {outputUnit || "unit"}</span><span className="font-mono">TZS {money(Math.round(totalCost))}k</span></div>
            </div>
          )}
        </div>
        <div className="px-5 sm:px-6 py-4 border-t border-slate-100 bg-white/95 backdrop-blur sticky bottom-0 z-10 flex gap-2">
          <button type="button" onClick={onClose} className="flex-1 text-[12px] font-medium border border-slate-200 rounded-lg py-2.5 hover:bg-slate-50">Cancel</button>
          <button type="submit" disabled={!valid} className="flex-1 text-[12px] font-medium btn-primary text-white rounded-lg py-2.5 disabled:opacity-40 disabled:cursor-not-allowed">Create BOM</button>
        </div>
      </form>
    </div>
  );
}

function WorkOrders({ workOrders, setWorkOrders, inventory, boms, loading }) {
  const [selected, setSelected] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [notice, setNotice] = useState(null);

  async function addWorkOrder(form) {
    const draft = {
      id: docId("WO"),
      bomId: form.bomId,
      product: boms.rows.find((b) => b.id === form.bomId)?.product || "Custom build",
      qty: Number(form.qty) || 1,
      status: "Planned",
      startDate: form.startDate,
      dueDate: form.dueDate,
      assignedTo: form.assignedTo || "Unassigned",
    };
    if (IS_CONFIGURED) {
      try {
        const header = await sb("manufacturing_work_orders").insert({
          bom_id: form.bomId, product: draft.product, qty: draft.qty, status: "Planned",
          start_date: form.startDate, due_date: form.dueDate, assigned_to: form.assignedTo,
        }).single().run();
        const confirmed = { ...mapWorkOrderRow(header), assignedTo: header.profiles?.full_name || draft.assignedTo };
        setWorkOrders((prev) => [confirmed, ...prev]);
        notify(`Work order ${confirmed.id} created`);
        return confirmed;
      } catch (e) {
        notify("Work order could not be saved to the server. Review the details and try again.", "error");
        return false;
      }
    }
    setWorkOrders((prev) => [draft, ...prev]);
    notify(`Work order ${draft.id} created`);
    return draft;
  }

  async function advanceOrder(id, next) {
    const order = workOrders.find((w) => w.id === id);
    if (!order) return false;

    // Completing a run actually consumes raw materials from Inventory —
    // the same shared table Inventory itself reads, so the deduction is
    // visible there immediately, not just inside Manufacturing.
    if (IS_CONFIGURED) {
      try {
        const inventoryUpdates = [];
        if (next === "Completed") {
          const bom = boms.rows.find((b) => b.id === order.bomId);
          if (!bom) throw new Error("The work order Bill of Materials is unavailable.");
          for (const c of bom.components) {
            const consumed = c.qty * order.qty;
            const item = inventory.rows.find((it) => it.sku === c.sku);
            if (!item || item.qty < consumed) throw new Error(`Insufficient confirmed stock for ${c.sku}.`);
            const savedItem = await sb("inventory_items").eq("sku", c.sku).update({ qty_on_hand: item.qty - consumed }).single().run();
            inventoryUpdates.push(mapInventoryRow(savedItem));
            await sb("inventory_stock_movements").insert({
              item_id: c.sku, movement: "Out", qty: consumed, reference: `${order.id} completed`,
            }).run();
          }
        }
        const savedOrder = await sb("manufacturing_work_orders").eq("id", order.dbId ?? order.id).update({ status: next }).single().run();
        const confirmed = { ...mapWorkOrderRow(savedOrder), assignedTo: savedOrder.profiles?.full_name || order.assignedTo };
        if (inventoryUpdates.length) {
          inventory.setRows((prev) => prev.map((item) => inventoryUpdates.find((updated) => updated.sku === item.sku) || item));
        }
        setWorkOrders((prev) => prev.map((existing) => (existing.id === id ? confirmed : existing)));
        setSelected((selectedOrder) => (selectedOrder && selectedOrder.id === id ? confirmed : selectedOrder));
        notify(next === "Completed" ? `${order.id} completed — server-confirmed materials deducted from Inventory` : `${order.id} marked ${next}`);
        return confirmed;
      } catch (e) {
        setNotice(`Work order could not be fully confirmed. The screen has not changed; reconcile this order and its stock before retrying because a server-side step may have completed.`);
        return false;
      }
    }

    if (next === "Completed") {
      const bom = boms.rows.find((b) => b.id === order.bomId);
      if (bom) {
        const shortages = [];
        inventory.setRows((prev) => prev.map((it) => {
          const comp = bom.components.find((c) => c.sku === it.sku);
          if (!comp) return it;
          const consumed = comp.qty * order.qty;
          if (consumed > it.qty) shortages.push(it.name);
          return { ...it, qty: Math.max(0, it.qty - consumed) };
        }));
        if (shortages.length) {
          setNotice(`Completed, but stock went negative-clamped for: ${shortages.join(", ")}. Check Inventory.`);
        } else {
          notify(`${order.id} completed — materials deducted from Inventory`);
        }

      }
    }
    const advanced = { ...order, status: next };
    setWorkOrders((prev) => prev.map((existing) => (existing.id === id ? advanced : existing)));
    setSelected((selectedOrder) => (selectedOrder && selectedOrder.id === id ? advanced : selectedOrder));
    return advanced;
  }

  async function deleteOrder(id) {
    const order = workOrders.find((w) => w.id === id);
    if (IS_CONFIGURED && order?.dbId) {
      try {
        await sb("manufacturing_work_orders").eq("id", order.dbId).delete().single().run();
        setWorkOrders((prev) => prev.filter((workOrder) => workOrder.id !== id));
        return true;
      } catch (e) {
        notify("Work order could not be deleted from the server. It remains available here.", "error");
        return false;
      }
    }
    setWorkOrders((prev) => prev.filter((workOrder) => workOrder.id !== id));
    return true;
  }


  // ── Production analytics ──────────────────────────────────────────────
  const planned   = workOrders.filter(w => w.status === "Planned").length;
  const inProg    = workOrders.filter(w => w.status === "In Progress").length;
  const completed = workOrders.filter(w => w.status === "Completed").length;
  const cancelled = workOrders.filter(w => w.status === "Cancelled").length;
  const total     = workOrders.length;
  const completionRate = total > 0 ? Math.round(completed / total * 100) : 0;
  const wipValue  = workOrders
    .filter(w => w.status !== "Cancelled")
    .reduce((s,w) => { const b = boms.rows.find(b => b.id === w.bomId); return s + (b ? bomUnitCost(b, inventory.rows) * w.qty : 0); }, 0);

  // Status breakdown for donut chart
  const statusChart = [
    {name:"Planned",     value:planned,   fill:"#3B82F6"},
    {name:"In Progress", value:inProg,    fill:"#F59E0B"},
    {name:"Completed",   value:completed, fill:"#16A34A"},
    {name:"Cancelled",   value:cancelled, fill:"#EF4444"},
  ].filter(d => d.value > 0);

  // Monthly completion trend (last 6 months)
  const woTrend = Array.from({length:6}, (_,i) => {
    const d = new Date(TODAY.getFullYear(), TODAY.getMonth()-5+i, 1);
    const key = d.toISOString().slice(0,7);
    const label = d.toLocaleString("default",{month:"short"});
    const monthWOs = workOrders.filter(w => (w.startDate||"").startsWith(key));
    return {
      month: label,
      planned:   monthWOs.filter(w=>w.status==="Planned").length,
      completed: monthWOs.filter(w=>w.status==="Completed").length,
      inProg:    monthWOs.filter(w=>w.status==="In Progress").length,
    };
  });
  return (
    <div className="space-y-5">
      {notice && (
        <div className="flex items-start justify-between gap-3 bg-[#F59E0B]/[0.07] border border-[#F59E0B]/20 text-[#8a670a] text-[12.5px] rounded-lg px-3.5 py-2.5">
          <span className="flex items-start gap-2"><AlertCircle size={14} className="shrink-0 mt-0.5" /> {notice}</span>
          <button onClick={() => setNotice(null)} className="text-[#8a670a]/60 hover:text-[#8a670a] shrink-0" aria-label="Dismiss notice"><X size={14} /></button>
        </div>
      )}
      {/* Production Analytics */}
      {workOrders.length > 0 && (
        <div className="space-y-3">
          {/* KPI tiles */}
          <div className="grid grid-cols-2 lg:grid-cols-5 gap-3">
            {[
              ["Total Orders", total,           "#2563EB"],
              ["In Progress",  inProg,          "#F59E0B"],
              ["Completed",    completed,        "#16A34A"],
              ["Completion %", completionRate+"%", completionRate>=80?"#16A34A":completionRate>=50?"#F59E0B":"#EF4444"],
              ["WIP Value",    "TZS "+money(Math.round(wipValue))+"k", "#7C3AED"],
            ].map(([l,v,col])=>(
              <div key={l} className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-3 text-center">
                <p className="text-[10.5px] text-slate-400 uppercase tracking-wide mb-1">{l}</p>
                <p className="text-[18px] font-bold" style={{color:col}}>{v}</p>
              </div>
            ))}
          </div>

          {/* Charts */}
          <div className="grid grid-cols-1 lg:grid-cols-2 gap-3">
            {/* Status PieChart */}
            <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4">
              <h3 className="text-[13.5px] font-semibold text-[#111827] mb-2">Work Order Status</h3>
              <div className="flex items-center gap-4">
                <ResponsiveContainer width="50%" height={120}>
                  <RPieChart>
                    <Pie data={statusChart} dataKey="value" cx="50%" cy="50%" outerRadius={50} innerRadius={28}>
                      {statusChart.map((d,i)=><Cell key={i} fill={d.fill}/>)}
                    </Pie>
                    <Tooltip formatter={(v,n)=>[v+" orders",n]}/>
                  </RPieChart>
                </ResponsiveContainer>
                <div className="flex-1 space-y-1.5">
                  {statusChart.map(d=>(
                    <div key={d.name} className="flex items-center justify-between">
                      <span className="flex items-center gap-1.5 text-[12px] text-slate-600">
                        <span className="w-2.5 h-2.5 rounded-full shrink-0" style={{background:d.fill}}/>
                        {d.name}
                      </span>
                      <span className="text-[13px] font-bold" style={{color:d.fill}}>{d.value}</span>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Monthly trend ComposedChart */}
            <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4">
              <h3 className="text-[13.5px] font-semibold text-[#111827] mb-2">Production Trend (6 months)</h3>
              <ResponsiveContainer width="100%" height={120}>
                <ComposedChart data={woTrend} margin={{left:-10,right:4,top:0,bottom:0}}>
                  <CartesianGrid vertical={false} stroke="#F3F4F6"/>
                  <XAxis dataKey="month" tick={{fontSize:10}} axisLine={false} tickLine={false}/>
                  <YAxis tick={{fontSize:9}} axisLine={false} tickLine={false}/>
                  <Tooltip/>
                  <Bar dataKey="planned"   fill="#93C5FD" radius={[2,2,0,0]} maxBarSize={20} name="Planned"/>
                  <Bar dataKey="inProg"    fill="#FCD34D" radius={[2,2,0,0]} maxBarSize={20} name="In Progress"/>
                  <Bar dataKey="completed" fill="#6EE7B7" radius={[2,2,0,0]} maxBarSize={20} name="Completed"/>
                </ComposedChart>
              </ResponsiveContainer>
            </div>
          </div>
        </div>
      )}
      <div className="flex justify-end">
        <button
          onClick={() => setShowForm(true)}
          className="btn-primary text-white text-[13px] font-medium px-3.5 py-2 rounded-lg flex items-center gap-1.5 shadow-sm transition-colors"
        >
          <Plus size={15} /> New Work Order
        </button>
      </div>

      <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-[13px] min-w-[740px]">
            <thead>
              <tr className="border-b border-slate-100 text-left text-[11px] text-slate-400 uppercase tracking-wide">
                <th className="px-4 py-3 font-medium">Work Order</th>
                <th className="px-4 py-3 font-medium">Product</th>
                <th className="px-4 py-3 font-medium text-right">Qty</th>
                <th className="px-4 py-3 font-medium">Due</th>
                <th className="px-4 py-3 font-medium">Assigned</th>
                <th className="px-4 py-3 font-medium">Status</th>
                <th className="px-4 py-3"></th>
              </tr>
            </thead>
            <tbody>
              {workOrders.map((w) => (
                <tr
                  key={w.id}
                  onClick={() => setSelected(w)}
                  className="border-b border-slate-50 last:border-0 hover:bg-slate-50/70 cursor-pointer transition-colors"
                >
                  <td className="px-4 py-3 font-mono text-[#111827] font-medium">{w.id}</td>
                  <td className="px-4 py-3 text-slate-700">{w.product}</td>
                  <td className="px-4 py-3 text-right font-mono">{w.qty}</td>
                  <td className="px-4 py-3 text-slate-500 font-mono">{w.dueDate}</td>
                  <td className="px-4 py-3 text-slate-500">{w.assignedTo}</td>
                  <td className="px-4 py-3">
                    <span
                      className="text-[11px] font-medium px-2 py-1 rounded-full inline-flex items-center gap-1.5"
                      style={{ backgroundColor: `${WO_STATUS_COLOR[w.status]}14`, color: WO_STATUS_COLOR[w.status] }}
                    >
                      <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: WO_STATUS_COLOR[w.status] }} />
                      {w.status}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-right"><ChevronRight size={15} className="text-slate-300 inline" /></td>
                </tr>
              ))}
              {loading && <SkeletonRows cols={7} />}
              {!loading && workOrders.length === 0 && (
                <tr>
                  <td colSpan={7}>
                    <EmptyState
                      icon={Factory}
                      title="No work orders yet"
                      hint="Schedule your first production run. Completing it will deduct the BOM's materials from Inventory automatically."
                      actionLabel="New Work Order"
                      onAction={() => setShowForm(true)}
                    />
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {selected && (
        <WorkOrderPanel order={selected} onClose={() => setSelected(null)} onAdvance={advanceOrder} onDelete={deleteOrder} inventory={inventory} boms={boms} />
      )}
      {showForm && <WorkOrderFormPanel boms={boms} inventory={inventory} onClose={() => setShowForm(false)} onSubmit={async (form) => {
        const created = await addWorkOrder(form);
        if (created) setShowForm(false);
        return created;
      }} />}
    </div>
  );
}

function WorkOrderPanel({ order, onClose, onAdvance, onDelete, inventory, boms }) {
  const bom = boms.rows.find((b) => b.id === order.bomId);
  const nextStatus = WO_STATUS_NEXT[order.status];
  const unitCost = bom ? bomUnitCost(bom, inventory.rows) : 0;
  const [saving, setSaving] = useState(false);

  // Live sufficiency check against the shared Inventory table — a component
  // is short if the required qty exceeds what is actually on hand right now.
  const requirements = (bom?.components || []).map((c) => {
    const item = inventory.rows.find((it) => it.sku === c.sku);
    const required = c.qty * order.qty;
    const onHand = item?.qty ?? 0;
    return { sku: c.sku, name: item?.name || c.sku, unit: item?.unit || "", required, onHand, short: required > onHand };
  });
  const hasShortage = requirements.some((r) => r.short);
  const completing = nextStatus === "Completed";

  async function advance() {
    if (saving) return;
    setSaving(true);
    try {
      await onAdvance(order.id, nextStatus);
    } finally {
      setSaving(false);
    }
  }

  async function removeOrder() {
    if (saving) return;
    setSaving(true);
    try {
      const deleted = await onDelete(order.id);
      if (deleted) onClose();
    } finally {
      setSaving(false);
    }
  }

  return (
    <div className="fixed inset-0 z-30 flex justify-end">
      <div className="absolute inset-0 bg-[#111827]/20 backdrop-blur-[2px]" onClick={onClose} />
      <div className="relative w-full sm:w-[420px] bg-white h-full rounded-l-[26px] border-l border-slate-200/80 shadow-2xl overflow-y-auto flex flex-col" style={{ animation: "slideIn .15s ease-out" }}>
        <div className="px-6 pt-6 pb-5 border-b border-slate-100">
          <div className="flex items-start justify-between mb-4">
            <div>
              <p className="text-[11px] font-mono text-slate-400">{order.id}</p>
              <h2 className="text-[17px] font-semibold text-[#111827] mt-0.5 leading-snug">{order.product}</h2>
            </div>
            <button onClick={onClose} className="text-slate-400 hover:text-slate-600 shrink-0" aria-label="Close"><X size={18} /></button>
          </div>
          <span
            className="text-[11px] font-medium px-2 py-1 rounded-full inline-flex items-center gap-1.5"
            style={{ backgroundColor: `${WO_STATUS_COLOR[order.status]}14`, color: WO_STATUS_COLOR[order.status] }}
          >
            <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: WO_STATUS_COLOR[order.status] }} />
            {order.status}
          </span>
        </div>

        <div className="px-6 py-5 flex-1">
          <div className="grid grid-cols-2 gap-3 mb-5">
            <div className="bg-slate-50 rounded-lg p-3">
              <p className="text-[11px] text-slate-400 mb-1">Quantity</p>
              <p className="text-[15px] font-mono font-semibold text-[#111827]">{order.qty} {bom?.outputUnit || "unit"}</p>
            </div>
            <div className="bg-slate-50 rounded-lg p-3">
              <p className="text-[11px] text-slate-400 mb-1">Est. Cost</p>
              <p className="text-[15px] font-mono font-semibold text-[#111827]">TZS {money(Math.round(unitCost * order.qty))}k</p>
            </div>
          </div>

          <div className="space-y-3 mb-6 text-[13px]">
            <div className="flex items-center gap-2.5 text-slate-600"><ClipboardList size={14} className="text-slate-400" /> {bom?.id} — {bom?.product}</div>
            <div className="flex items-center gap-2.5 text-slate-600"><Star size={14} className="text-slate-400" /> Assigned to {order.assignedTo}</div>
            <div className="flex items-center gap-2.5 text-slate-600"><Clock size={14} className="text-slate-400" /> {order.startDate} → {order.dueDate}</div>
          </div>

          {bom && (
            <div>
              <p className="text-[11px] text-slate-400 mb-2 uppercase tracking-wide">Material requirement (×{order.qty})</p>
              <div className="border border-slate-100 rounded-lg overflow-hidden">
                {requirements.map((r, i) => (
                  <div key={i} className={`flex items-center justify-between px-3 py-2.5 text-[13px] ${i !== requirements.length - 1 ? "border-b border-slate-50" : ""}`}>
                    <div className="min-w-0 pr-2">
                      <p className="text-slate-700 truncate">{r.name}</p>
                      <p className={`text-[11px] font-mono ${r.short ? "text-[#EF4444]" : "text-slate-400"}`}>
                        {r.onHand} {r.unit} on hand{r.short ? " — insufficient" : ""}
                      </p>
                    </div>
                    <span className={`font-mono shrink-0 ${r.short ? "text-[#EF4444] font-medium" : "text-[#111827]"}`}>
                      {r.required} {r.unit}
                    </span>
                  </div>
                ))}
              </div>
              {order.status !== "Completed" && hasShortage && (
                <div className="flex items-start gap-2.5 bg-[#EF4444]/5 border border-[#EF4444]/20 rounded-lg p-3 mt-3">
                  <AlertCircle size={15} className="text-[#EF4444] shrink-0 mt-0.5" />
                  <p className="text-[12.5px] text-[#EF4444] leading-snug">
                    Inventory can't fully cover this run. Restock the flagged components or reduce the quantity before completing.
                  </p>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="px-6 py-4 border-t border-slate-100 flex flex-col gap-2">
          {nextStatus && (
            <button
              onClick={advance}
              disabled={saving || (completing && hasShortage)}
              className="text-[12px] font-medium btn-primary text-white rounded-lg py-2.5 transition-colors disabled:opacity-40 disabled:cursor-not-allowed"
            >
              {saving ? "Saving…" : completing && hasShortage ? "Insufficient stock to complete" : `Mark ${nextStatus}`}
            </button>
          )}
          <ConfirmDeleteButton label={saving ? "Saving…" : "Delete work order"} onConfirm={removeOrder} />
        </div>
      </div>
    </div>
  );
}

function WorkOrderFormPanel({ boms, inventory, onClose, onSubmit }) {
  const [form, setForm] = useState({ bomId: boms.rows[0]?.id || "", qty: "", startDate: TODAY.toISOString().slice(0, 10), dueDate: "", assignedTo: "" });
  const [touched, setTouched] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const valid = Number(form.qty) > 0 && form.dueDate;
  const bom = boms.rows.find((b) => b.id === form.bomId);

  function set(key, val) { setForm((f) => ({ ...f, [key]: val })); }
  async function handleSubmit(e) {
    e.preventDefault();
    setTouched(true);
    if (!valid || submitting) return;
    setSubmitting(true);
    try {
      await onSubmit(form);
    } finally {
      setSubmitting(false);
    }
  }

  return (
    <div className="fixed inset-0 z-30 flex justify-end">
      <div className="absolute inset-0 bg-[#111827]/20 backdrop-blur-[2px]" onClick={onClose} />
      <form onSubmit={handleSubmit} className="relative w-full sm:w-[420px] bg-white h-full rounded-l-[26px] border-l border-slate-200/80 shadow-2xl overflow-y-auto flex flex-col" style={{ animation: "slideIn .15s ease-out" }}>
        <div className="px-5 sm:px-6 pt-5 sm:pt-6 pb-4 sm:pb-5 border-b border-slate-100 bg-white/95 backdrop-blur sticky top-0 z-10 flex items-start justify-between">
          <div>
            <p className="text-[11px] text-slate-400 uppercase tracking-wide">Manufacturing</p>
            <h2 className="text-[18px] font-semibold text-[#111827] mt-0.5">New Work Order</h2>
          </div>
          <button type="button" onClick={onClose} className="text-slate-400 hover:text-slate-600" aria-label="Close"><X size={18} /></button>
        </div>

        <div className="px-5 sm:px-6 py-5 flex-1 space-y-4">
          <FormField label="Bill of Materials">
            <select className={inputClass} value={form.bomId} onChange={(e) => set("bomId", e.target.value)}>
              {boms.rows.map((b) => <option key={b.id} value={b.id}>{b.product}</option>)}
            </select>
          </FormField>

          <FormField label={`Quantity (${bom?.outputUnit || "unit"})`} required>
            <input type="number" min="1" className={inputClass} value={form.qty} onChange={(e) => set("qty", e.target.value)} placeholder="0" />
            {touched && !(Number(form.qty) > 0) && <p className="text-[11px] text-[#EF4444] mt-1">Enter a quantity.</p>}
          </FormField>

          <div className="grid grid-cols-2 gap-3">
            <FormField label="Start date">
              <input type="date" className={inputClass} value={form.startDate} onChange={(e) => set("startDate", e.target.value)} />
            </FormField>
            <FormField label="Due date" required>
              <input type="date" className={inputClass} value={form.dueDate} onChange={(e) => set("dueDate", e.target.value)} />
              {touched && !form.dueDate && <p className="text-[11px] text-[#EF4444] mt-1">Due date is required.</p>}
            </FormField>
          </div>

          <FormField label="Assigned to">
            <input className={inputClass} value={form.assignedTo} onChange={(e) => set("assignedTo", e.target.value)} placeholder="e.g. Grace Mmbaga" />
          </FormField>

          {bom && (
            <div className="bg-slate-50 rounded-lg p-3 text-[12.5px] text-slate-500">
              Est. cost: <span className="font-mono text-[#111827] font-medium">TZS {money(Math.round(bomUnitCost(bom, inventory.rows) * (Number(form.qty) || 0)))}k</span> for {form.qty || 0} {bom.outputUnit}(s)
            </div>
          )}
        </div>

        <div className="px-5 sm:px-6 py-4 border-t border-slate-100 bg-white/95 backdrop-blur sticky bottom-0 z-10 flex gap-2">
          <button type="button" onClick={onClose} className="flex-1 text-[12px] font-medium border border-slate-200 rounded-lg py-2.5 hover:bg-slate-50 transition-colors">Cancel</button>
          <button type="submit" disabled={submitting} className="flex-1 text-[12px] font-medium btn-primary text-white rounded-lg py-2.5 transition-colors disabled:opacity-50">{submitting ? "Saving…" : "Create Work Order"}</button>
        </div>
      </form>
    </div>
  );
}

/* ------------------------------ MACHINES ------------------------------------- */

function Machines() {
  const machines = useCompanyTable("manufacturing_machines", machinesSeed, { order: { col: "name", ascending: true }, mapRow: mapMachineRow });
  const { rows, setRows, loading } = machines;
  const [showForm, setShowForm] = useState(false);
  const [selected, setSelected] = useState(null);

  async function addMachine(form) {
    const draft = { id: docId("MC"), name: form.name, type: form.type, warehouse: form.warehouse, status: "Idle", purchaseDate: form.purchaseDate };
    setRows((prev) => [draft, ...prev]);
    setShowForm(false);
    notify(`Machine added: ${draft.name}`);
    if (IS_CONFIGURED) {
      try {
        const header = await sb("manufacturing_machines").insert({
          name: draft.name, machine_type: draft.type, warehouse_id: draft.warehouse, status: "Idle", purchase_date: draft.purchaseDate,
        }).single().run();
        if (header?.id) setRows((prev) => prev.map((m) => (m.id === draft.id ? { ...m, dbId: header.id } : m)));
      } catch (_e) { notify("Machine added locally, but saving to the server failed.", "error"); }
    }
  }

  async function setStatus(id, status) {
    const m = rows.find((x) => x.id === id);
    setRows((prev) => prev.map((x) => (x.id === id ? { ...x, status } : x)));
    setSelected((s) => (s && s.id === id ? { ...s, status } : s));
    if (IS_CONFIGURED && m?.dbId) {
      try { await sb("manufacturing_machines").eq("id", m.dbId).update({ status }).run(); } catch (_e) { notify("Couldn't save the machine status to the server.", "error"); }
    }
  }

  async function deleteMachine(id) {
    const m = rows.find((x) => x.id === id);
    setRows((prev) => prev.filter((x) => x.id !== id));
    setSelected(null);
    if (IS_CONFIGURED && m?.dbId) {
      try { await sb("manufacturing_machines").eq("id", m.dbId).delete().run(); } catch (_e) { notify("Couldn't delete the machine on the server.", "error"); }
    }
  }

  return (
    <div className="space-y-5">
      <div className="flex justify-end">
        <button onClick={() => setShowForm(true)} className="btn-primary text-white text-[13px] font-medium px-3.5 py-2 rounded-lg flex items-center gap-1.5 shadow-sm">
          <Plus size={15} /> New Machine
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4">
        {loading && Array.from({ length: 3 }).map((_, i) => <div key={i} className="bg-white rounded-xl border border-slate-200/80 h-28 skeleton-shimmer" />)}
        {!loading && rows.map((m) => {
          const wh = WAREHOUSES.find((w) => w.id === m.warehouse);
          return (
            <button key={m.id} onClick={() => setSelected(m)} className="text-left bg-white rounded-xl border border-slate-200/80 shadow-sm p-4 hover:border-[#16A34A]/50 hover:shadow-md transition-all">
              <div className="flex items-center gap-2.5 mb-3">
                <div className="w-9 h-9 rounded-lg bg-[#111827]/5 flex items-center justify-center"><Cog size={16} className="text-[#111827]" /></div>
                <div><p className="text-[13.5px] font-semibold text-[#111827]">{m.name}</p><p className="text-[11px] text-slate-400">{m.type} · {wh?.city}</p></div>
              </div>
              <span className="text-[11px] font-medium px-2 py-1 rounded-full inline-flex items-center gap-1.5" style={{ backgroundColor: `${MACHINE_STATUS_COLOR[m.status]}14`, color: MACHINE_STATUS_COLOR[m.status] }}>
                <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: MACHINE_STATUS_COLOR[m.status] }} />{m.status}
              </span>
            </button>
          );
        })}
        {!loading && rows.length === 0 && (
          <div className="col-span-full bg-white rounded-xl border border-slate-200/80 shadow-sm">
            <EmptyState icon={Cog} title="No machines registered yet" hint="Track production equipment status and maintenance history here." actionLabel="New Machine" onAction={() => setShowForm(true)} />
          </div>
        )}
      </div>

      {selected && (
        <div className="fixed inset-0 z-30 flex justify-end">
          <div className="absolute inset-0 bg-[#111827]/20 backdrop-blur-[2px]" onClick={() => setSelected(null)} />
          <div className="relative w-full sm:w-[380px] bg-white h-full rounded-l-[26px] border-l border-slate-200/80 shadow-2xl p-6 overflow-y-auto flex flex-col" style={{ animation: "slideIn .15s ease-out" }}>
            <div className="flex items-start justify-between mb-6">
              <div><h2 className="text-[17px] font-semibold text-[#111827]">{selected.name}</h2><p className="text-[13px] text-slate-500">{selected.type}</p></div>
              <button onClick={() => setSelected(null)} className="text-slate-400 hover:text-slate-600" aria-label="Close"><X size={18} /></button>
            </div>
            <div className="mb-6">
              <p className="text-[11px] font-medium text-slate-500 mb-2">Status</p>
              <div className="grid grid-cols-2 gap-1.5">
                {Object.keys(MACHINE_STATUS_COLOR).map((s) => (
                  <button key={s} onClick={() => setStatus(selected.id, s)} className={`text-[11.5px] font-medium rounded-lg py-2 border transition-colors ${selected.status === s ? "border-[#16A34A] bg-[#16A34A]/8 text-[#111827]" : "border-slate-200 text-slate-500 hover:bg-slate-50"}`}>
                    {s}
                  </button>
                ))}
              </div>
            </div>
            <div className="flex items-center gap-2.5 text-[13px] text-slate-600 mb-6"><Clock size={14} className="text-slate-400" /> Purchased {selected.purchaseDate}</div>
            <div className="flex-1" />
            <ConfirmDeleteButton label="Remove machine" onConfirm={() => deleteMachine(selected.id)} />
          </div>
        </div>
      )}
      {showForm && <MachineFormPanel onClose={() => setShowForm(false)} onSubmit={addMachine} />}
    </div>
  );
}

function MachineFormPanel({ onClose, onSubmit }) {
  const [form, setForm] = useState({ name: "", type: "", warehouse: WAREHOUSES[0].id, purchaseDate: TODAY.toISOString().slice(0, 10) });
  function set(key, val) { setForm((f) => ({ ...f, [key]: val })); }
  function handleSubmit(e) { e.preventDefault(); if (!form.name.trim()) return; onSubmit(form); }

  return (
    <div className="fixed inset-0 z-30 flex justify-end">
      <div className="absolute inset-0 bg-[#111827]/20 backdrop-blur-[2px]" onClick={onClose} />
      <form onSubmit={handleSubmit} className="relative w-full sm:w-[380px] bg-white h-full rounded-l-[26px] border-l border-slate-200/80 shadow-2xl overflow-y-auto flex flex-col" style={{ animation: "slideIn .15s ease-out" }}>
        <div className="px-5 sm:px-6 pt-5 sm:pt-6 pb-4 sm:pb-5 border-b border-slate-100 bg-white/95 backdrop-blur sticky top-0 z-10 flex items-start justify-between">
          <div><p className="text-[11px] text-slate-400 uppercase tracking-wide">Manufacturing</p><h2 className="text-[18px] font-semibold text-[#111827] mt-0.5">New Machine</h2></div>
          <button type="button" onClick={onClose} className="text-slate-400 hover:text-slate-600" aria-label="Close"><X size={18} /></button>
        </div>
        <div className="px-5 sm:px-6 py-5 flex-1 space-y-4">
          <FormField label="Machine name" required><input className={inputClass} value={form.name} onChange={(e) => set("name", e.target.value)} placeholder="e.g. CNC Panel Cutter #2" /></FormField>
          <FormField label="Type"><input className={inputClass} value={form.type} onChange={(e) => set("type", e.target.value)} placeholder="e.g. Cutting" /></FormField>
          <FormField label="Location">
            <select className={inputClass} value={form.warehouse} onChange={(e) => set("warehouse", e.target.value)}>
              {WAREHOUSES.map((w) => <option key={w.id} value={w.id}>{w.name}</option>)}
            </select>
          </FormField>
          <FormField label="Purchase date"><input type="date" className={inputClass} value={form.purchaseDate} onChange={(e) => set("purchaseDate", e.target.value)} /></FormField>
        </div>
        <div className="px-5 sm:px-6 py-4 border-t border-slate-100 bg-white/95 backdrop-blur sticky bottom-0 z-10 flex gap-2">
          <button type="button" onClick={onClose} className="flex-1 text-[12px] font-medium border border-slate-200 rounded-lg py-2.5 hover:bg-slate-50">Cancel</button>
          <button type="submit" className="flex-1 text-[12px] font-medium btn-primary text-white rounded-lg py-2.5">Add Machine</button>
        </div>
      </form>
    </div>
  );
}

/* --------------------------------- QUALITY CONTROL --------------------------------- */

function QualityControl({ workOrders }) {
  const inspections = useCompanyTable("manufacturing_qc_inspections", qcInspectionsSeed, { order:{ col:"inspection_date", ascending:false }, mapRow:mapQcInspectionRow });
  const { rows, setRows, loading } = inspections;
  const [showForm, setShowForm] = useState(false);

  const passRate   = rows.length ? Math.round(rows.filter(r=>r.result==="Pass").length/rows.length*100) : null;
  const passColor  = passRate===null?"#6B7280":passRate>=90?"#16A34A":passRate>=70?"#F59E0B":"#EF4444";
  const failedWOs  = rows.filter(r=>r.result==="Fail");

  // Trend: last 6 months pass rate
  const trend = useMemo(()=>Array.from({length:6},(_,i)=>{
    const d = new Date(TODAY.getFullYear(), TODAY.getMonth()-5+i, 1);
    const key = d.toISOString().slice(0,7);
    const monthRows = rows.filter(r=>(r.inspection_date||"").startsWith(key));
    const passed = monthRows.filter(r=>r.result==="Pass").length;
    const rate   = monthRows.length>0?Math.round(passed/monthRows.length*100):null;
    return {month:d.toLocaleString("default",{month:"short"}), rate, total:monthRows.length, passed};
  }), [rows]);

  // Defect categories
  const defects = useMemo(()=>{
    const map={};
    rows.filter(r=>r.result==="Fail"&&r.defects).forEach(r=>{
      (r.defects||"").split(",").map(d=>d.trim()).forEach(d=>{ if(d) map[d]=(map[d]||0)+1; });
    });
    return Object.entries(map).sort((a,b)=>b[1]-a[1]).slice(0,6).map(([name,value])=>({name,value}));
  }, [rows]);

  async function addInspection(form) {
    const draft = { id:docId("QC"), workOrderId:form.workOrderId, inspector:form.inspector, result:form.result, defects:form.defects||"", notes:form.notes, inspection_date:TODAY.toISOString().slice(0,10) };
    setRows(p=>[draft,...p]);
    setShowForm(false);
    notify("QC "+form.result+" recorded for "+form.workOrderId);
    logAudit("QC Inspection: "+form.result,"Manufacturing","QC",form.workOrderId);
    if (IS_CONFIGURED) { try { await sb("manufacturing_qc_inspections").insert({work_order_id:draft.workOrderId,inspector:draft.inspector,result:draft.result,defects:draft.defects,notes:draft.notes,inspection_date:draft.inspection_date}).run(); } catch(_e){} }
  }

  return (
    <div className="space-y-4">
      {/* Header */}
      <div className="grid grid-cols-2 lg:grid-cols-4 gap-3">
        {[
          ["Total Inspections", rows.length,                                "#2563EB"],
          ["Pass Rate",         passRate!==null?passRate+"%":"—",          passColor],
          ["Passed",            rows.filter(r=>r.result==="Pass").length,   "#16A34A"],
          ["Failed",            rows.filter(r=>r.result==="Fail").length,   "#EF4444"],
        ].map(([l,v,col])=>(
          <div key={l} className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4 text-center">
            <p className="text-[11px] text-slate-400 uppercase tracking-wide mb-1">{l}</p>
            <p className="text-[22px] font-bold" style={{color:col}}>{v}</p>
          </div>
        ))}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
        {/* Pass rate trend */}
        <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4">
          <h3 className="text-[13.5px] font-semibold text-[#111827] mb-3">Pass Rate Trend (6 months)</h3>
          <ResponsiveContainer width="100%" height={140}>
            <ComposedChart data={trend} margin={{left:-10,right:4,top:0,bottom:0}}>
              <CartesianGrid vertical={false} stroke="#F3F4F6"/>
              <XAxis dataKey="month" tick={{fontSize:10}} axisLine={false} tickLine={false}/>
              <YAxis domain={[0,100]} tick={{fontSize:10}} axisLine={false} tickLine={false} tickFormatter={v=>v+"%"}/>
              <Tooltip formatter={(v,n)=>[n==="rate"?v+"%":v+" inspections",n==="rate"?"Pass Rate":"Total"]}/>
              <Bar dataKey="total"  fill="#E5E7EB" radius={[3,3,0,0]} name="total" maxBarSize={30}/>
              <Line type="monotone" dataKey="rate" stroke={passColor} strokeWidth={2.5} dot={{r:4,fill:passColor}} connectNulls/>
            </ComposedChart>
          </ResponsiveContainer>
          {passRate!==null && (
            <div className="mt-3 flex items-center gap-2">
              <div className="flex-1 h-2 bg-slate-100 rounded-full overflow-hidden">
                <div className="h-full rounded-full" style={{width:passRate+"%",background:passColor}}/>
              </div>
              <span className="text-[12px] font-bold shrink-0" style={{color:passColor}}>{passRate}%</span>
              <span className="text-[11px] text-slate-400 shrink-0">{passRate>=90?"Excellent":passRate>=70?"Acceptable":"Needs Attention"}</span>
            </div>
          )}
        </div>

        {/* Defect categories */}
        <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4">
          <h3 className="text-[13.5px] font-semibold text-[#111827] mb-3">Top Defect Categories</h3>
          {defects.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-[140px] text-slate-300">
              <CheckCircle2 size={32} className="mb-2"/>
              <p className="text-[12.5px]">No defects recorded</p>
            </div>
          ) : (
            <ResponsiveContainer width="100%" height={140}>
              <BarChart data={defects} layout="vertical" margin={{left:5,right:20,top:0,bottom:0}}>
                <XAxis type="number" tick={{fontSize:10}} axisLine={false} tickLine={false}/>
                <YAxis dataKey="name" type="category" tick={{fontSize:11}} axisLine={false} tickLine={false} width={80}/>
                <Tooltip formatter={v=>[v+" occurrences","Defects"]}/>
                <Bar dataKey="value" fill="#EF4444" radius={[0,5,5,0]} maxBarSize={20}/>
              </BarChart>
            </ResponsiveContainer>
          )}
        </div>
      </div>

      {/* Failed inspections alert */}
      {failedWOs.length > 0 && (
        <div className="bg-red-50 border border-red-200 rounded-xl p-4">
          <p className="text-[13px] font-semibold text-red-700 mb-2">⚠ {failedWOs.length} Failed Inspection{failedWOs.length>1?"s":""} — Requires Action</p>
          <div className="flex flex-wrap gap-2">
            {failedWOs.slice(0,5).map(f=>(
              <span key={f.id} className="text-[11.5px] bg-white border border-red-200 text-red-600 px-2.5 py-1 rounded-lg font-medium">
                {f.workOrderId} · {f.inspector}
              </span>
            ))}
          </div>
        </div>
      )}

      {/* Controls */}
      <div className="flex justify-end">
        <button onClick={()=>setShowForm(true)} className="flex items-center gap-1.5 text-[12.5px] font-semibold text-white px-4 py-2.5 rounded-xl bg-[#16A34A]">
          <Plus size={13}/>Log Inspection
        </button>
      </div>

      {showForm && (
        <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-5 space-y-3">
          <p className="text-[14px] font-semibold text-[#111827]">New QC Inspection</p>
          <QcFormPanel workOrders={workOrders} onClose={()=>setShowForm(false)} onSubmit={addInspection}/>
        </div>
      )}

      {/* Inspections table */}
      <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm overflow-hidden">
        <div className="px-4 py-3 border-b border-slate-100">
          <p className="text-[13.5px] font-semibold text-[#111827]">Inspection Log ({rows.length})</p>
        </div>
        {rows.length === 0 ? (
          <p className="text-center text-slate-400 py-10">No inspections recorded yet</p>
        ) : (
          <table className="w-full text-[12.5px]">
            <thead><tr className="border-b border-slate-100 bg-slate-50">{["Work Order","Inspector","Date","Result","Defects","Notes"].map(h=>(
              <th key={h} className="px-4 py-3 text-left text-[10.5px] font-medium uppercase tracking-wide text-slate-400">{h}</th>
            ))}</tr></thead>
            <tbody>{rows.map(r=>{
              const col = r.result==="Pass"?"#16A34A":"#EF4444";
              return (
                <tr key={r.id} className="border-b border-slate-50 last:border-0 hover:bg-slate-50/50">
                  <td className="px-4 py-3 font-mono font-semibold text-[#111827]">{r.workOrderId}</td>
                  <td className="px-4 py-3 text-slate-500">{r.inspector}</td>
                  <td className="px-4 py-3 font-mono text-[11.5px] text-slate-400">{r.inspection_date}</td>
                  <td className="px-4 py-3"><span className="text-[10.5px] font-bold px-2 py-0.5 rounded-full" style={{background:col+"18",color:col}}>{r.result}</span></td>
                  <td className="px-4 py-3 text-slate-400 text-[11.5px] max-w-[140px] truncate">{r.defects||"—"}</td>
                  <td className="px-4 py-3 text-slate-400 text-[11.5px] max-w-[120px] truncate">{r.notes||"—"}</td>
                </tr>
              );
            })}</tbody>
          </table>
        )}
      </div>
    </div>
  );
}

// (fragment removed)




function QcFormPanel({ workOrders, onClose, onSubmit }) {
  const completedOrders = workOrders.filter((w) => w.status === "Completed");
  const [form, setForm] = useState({ workOrderId: completedOrders[0]?.id || "", inspector: "", result: "Pass", defectsFound: "0", notes: "" });
  function set(key, val) { setForm((f) => ({ ...f, [key]: val })); }
  function handleSubmit(e) { e.preventDefault(); if (!form.workOrderId || !form.inspector.trim()) return; onSubmit(form); }

  return (
    <div className="fixed inset-0 z-30 flex justify-end">
      <div className="absolute inset-0 bg-[#111827]/20 backdrop-blur-[2px]" onClick={onClose} />
      <form onSubmit={handleSubmit} className="relative w-full sm:w-[400px] bg-white h-full rounded-l-[26px] border-l border-slate-200/80 shadow-2xl overflow-y-auto flex flex-col" style={{ animation: "slideIn .15s ease-out" }}>
        <div className="px-5 sm:px-6 pt-5 sm:pt-6 pb-4 sm:pb-5 border-b border-slate-100 bg-white/95 backdrop-blur sticky top-0 z-10 flex items-start justify-between">
          <div><p className="text-[11px] text-slate-400 uppercase tracking-wide">Quality Control</p><h2 className="text-[18px] font-semibold text-[#111827] mt-0.5">Log Inspection</h2></div>
          <button type="button" onClick={onClose} className="text-slate-400 hover:text-slate-600" aria-label="Close"><X size={18} /></button>
        </div>
        <div className="px-5 sm:px-6 py-5 flex-1 space-y-4">
          <FormField label="Work order">
            {completedOrders.length === 0 ? (
              <p className="text-[12.5px] text-slate-400">No completed work orders yet to inspect.</p>
            ) : (
              <select className={inputClass} value={form.workOrderId} onChange={(e) => set("workOrderId", e.target.value)}>
                {completedOrders.map((w) => <option key={w.id} value={w.id}>{w.id} — {w.product}</option>)}
              </select>
            )}
          </FormField>
          <FormField label="Inspector" required><input className={inputClass} value={form.inspector} onChange={(e) => set("inspector", e.target.value)} placeholder="e.g. David Chen" /></FormField>
          <div className="grid grid-cols-2 gap-3">
            <FormField label="Result">
              <select className={inputClass} value={form.result} onChange={(e) => set("result", e.target.value)}>
                {Object.keys(QC_RESULT_COLOR).map((r) => <option key={r} value={r}>{r}</option>)}
              </select>
            </FormField>
            <FormField label="Defects found"><input type="number" min="0" className={inputClass} value={form.defectsFound} onChange={(e) => set("defectsFound", e.target.value)} /></FormField>
          </div>
          <FormField label="Notes"><textarea className={inputClass} rows={3} value={form.notes} onChange={(e) => set("notes", e.target.value)} placeholder="Inspection findings..." /></FormField>
        </div>
        <div className="px-5 sm:px-6 py-4 border-t border-slate-100 bg-white/95 backdrop-blur sticky bottom-0 z-10 flex gap-2">
          <button type="button" onClick={onClose} className="flex-1 text-[12px] font-medium border border-slate-200 rounded-lg py-2.5 hover:bg-slate-50">Cancel</button>
          <button type="submit" disabled={completedOrders.length === 0} className="flex-1 text-[12px] font-medium btn-primary text-white rounded-lg py-2.5 disabled:opacity-40 disabled:cursor-not-allowed">Log Inspection</button>
        </div>
      </form>
    </div>
  );
}

/* --------------------------------- MAINTENANCE --------------------------------- */

function Maintenance({ expensesHook }) {
  const records = useCompanyTable("manufacturing_maintenance", maintenanceSeed, { order: { col: "maintenance_date", ascending: false }, mapRow: mapMaintenanceRow });
  const { rows, setRows, loading } = records;
  const [showForm, setShowForm] = useState(false);
  const [savingMaintenance, setSavingMaintenance] = useState(false);
  const todayStr = TODAY.toISOString().slice(0, 10);
  const overdue = rows.filter((r) => r.nextDueDate && r.nextDueDate < todayStr);

  async function addRecord(form) {
    if (savingMaintenance) return;
    const draft = {
      id: docId("MT"), machine: form.machine, type: form.type, technician: form.technician,
      date: TODAY.toISOString().slice(0, 10), cost: Number(form.cost) || 0, notes: form.notes, nextDueDate: form.nextDueDate || null,
    };
    setSavingMaintenance(true);
    try {
      if (!IS_CONFIGURED) {
        setRows((prev) => [draft, ...prev]);
        if (draft.cost > 0) expensesHook.setRows((prev) => [{ id: docId("EX"), vendor: `Maintenance — ${draft.machine}`, category: "Maintenance", date: draft.date, dueDate: draft.date, amount: draft.cost, status: "Paid", method: "Cash" }, ...prev]);
        setShowForm(false);
        notify(`Maintenance logged: ${draft.machine}`);
        return;
      }
      const { data, error } = await runCompanyTableMutation("manufacturing_maintenance", "insert", {
        machine_name: draft.machine, maintenance_type: draft.type, technician: draft.technician,
        maintenance_date: draft.date, cost: draft.cost, notes: draft.notes, next_due_date: draft.nextDueDate,
      });
      if (error || !data?.id) throw error || new Error("The server did not return the maintenance record.");
      const confirmed = mapMaintenanceRow(data);
      setRows((prev) => [confirmed, ...prev]);
      setShowForm(false);
      notify(`Maintenance logged: ${confirmed.machine}`);
      if (draft.cost > 0) {
        const { data: expenseData, error: expenseError } = await runCompanyTableMutation("finance_expenses", "insert", {
          vendor: `Maintenance — ${draft.machine}`, category: "Maintenance", expense_date: draft.date,
          due_date: draft.date, amount: draft.cost, status: "Paid", method: "Cash",
        });
        if (expenseError || !expenseData?.id) {
          notify("Maintenance is confirmed, but its linked Finance expense needs reconciliation and retry.", "error");
        } else {
          expensesHook.setRows((prev) => [mapExpenseRow(expenseData), ...prev]);
        }
      }
    } catch (error) {
      notify(`Maintenance was not logged. ${error?.message || "Your form is still available to retry."}`, "error");
    } finally {
      setSavingMaintenance(false);
    }
  }

  return (
    <div className="space-y-5">
      {overdue.length > 0 && (
        <div className="flex items-start gap-2.5 bg-[#EF4444]/5 border border-[#EF4444]/20 rounded-lg p-3">
          <AlertCircle size={15} className="text-[#EF4444] shrink-0 mt-0.5" />
          <p className="text-[12px] text-[#8a1a15] leading-relaxed">
            {overdue.length} machine{overdue.length > 1 ? "s are" : " is"} past due for maintenance: {overdue.map((r) => r.machine).join(", ")}.
          </p>
        </div>
      )}
      {/* Maintenance Analytics */}
      {rows.length > 0 && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-3">
          {/* Monthly cost BarChart */}
          <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4">
            <h3 className="text-[13.5px] font-semibold text-[#111827] mb-3">Monthly Maintenance Cost</h3>
            {(() => {
              const months = Array.from({length:6},(_,i)=>{
                const d = new Date(TODAY.getFullYear(),TODAY.getMonth()-5+i,1);
                const key = d.toISOString().slice(0,7);
                const cost = rows.filter(r=>(r.date||"").startsWith(key)).reduce((s,r)=>s+r.cost,0);
                return {month:d.toLocaleString("default",{month:"short"}), cost:Math.round(cost)};
              });
              const totalCost = rows.reduce((s,r)=>s+r.cost,0);
              return (
                <div>
                  <p className="text-[12px] text-slate-400 mb-2">YTD total: <strong className="text-[#111827]">TZS {money(Math.round(totalCost))}k</strong></p>
                  <ResponsiveContainer width="100%" height={120}>
                    <BarChart data={months} margin={{left:-10,right:4,top:0,bottom:0}}>
                      <CartesianGrid vertical={false} stroke="#F3F4F6"/>
                      <XAxis dataKey="month" tick={{fontSize:10}} axisLine={false} tickLine={false}/>
                      <YAxis tick={{fontSize:9}} axisLine={false} tickLine={false}/>
                      <Tooltip formatter={(v)=>["TZS "+money(v)+"k","Cost"]}/>
                      <Bar dataKey="cost" fill="#EF4444" radius={[4,4,0,0]}/>
                    </BarChart>
                  </ResponsiveContainer>
                </div>
              );
            })()}
          </div>

          {/* Upcoming maintenance schedule */}
          <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4">
            <h3 className="text-[13.5px] font-semibold text-[#111827] mb-3">Upcoming Schedule</h3>
            <div className="space-y-2">
              {(() => {
                const upcoming = rows
                  .filter(r => r.nextDueDate)
                  .sort((a,b) => new Date(a.nextDueDate) - new Date(b.nextDueDate))
                  .slice(0,5);
                if (upcoming.length === 0) return <p className="text-slate-400 text-[12.5px] text-center py-4">No upcoming maintenance scheduled</p>;
                return upcoming.map(r => {
                  const due     = new Date(r.nextDueDate);
                  const daysLeft = Math.ceil((due - TODAY) / 86400000);
                  const isOverdue = daysLeft < 0;
                  const isSoon    = daysLeft >= 0 && daysLeft <= 7;
                  const col = isOverdue ? "#EF4444" : isSoon ? "#F59E0B" : "#16A34A";
                  return (
                    <div key={r.id} className="flex items-center gap-3 p-2.5 rounded-xl border" style={{borderColor:col+"30",background:col+"05"}}>
                      <div className="w-10 h-10 rounded-xl flex items-center justify-center shrink-0 text-white font-bold text-[11px] text-center leading-tight" style={{background:col}}>
                        {isOverdue ? "PAST" : daysLeft+"d"}
                      </div>
                      <div className="flex-1 min-w-0">
                        <p className="text-[13px] font-semibold text-[#111827] truncate">{r.machine}</p>
                        <p className="text-[11px] text-slate-400">{r.type} · {r.nextDueDate}</p>
                      </div>
                    </div>
                  );
                });
              })()}
            </div>
          </div>
        </div>
      )}

            <div className="flex justify-end">
        <button onClick={() => setShowForm(true)} className="btn-primary text-white text-[13px] font-medium px-3.5 py-2 rounded-lg flex items-center gap-1.5 shadow-sm">
          <Plus size={15} /> Log Maintenance
        </button>
      </div>
      <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-[13px] min-w-[720px]">
            <thead><tr className="border-b border-slate-100 text-left text-[11px] text-slate-400 uppercase tracking-wide">
              <th className="px-4 py-3 font-medium">Machine</th><th className="px-4 py-3 font-medium">Type</th><th className="px-4 py-3 font-medium">Technician</th><th className="px-4 py-3 font-medium">Next Due</th><th className="px-4 py-3 font-medium text-right">Cost (TZS 000)</th>
            </tr></thead>
            <tbody>
              {loading && <SkeletonRows cols={5} />}
              {!loading && rows.map((r) => {
                const isOverdue = r.nextDueDate && r.nextDueDate < todayStr;
                return (
                  <tr key={r.id} className="border-b border-slate-50 last:border-0">
                    <td className="px-4 py-3 font-medium text-[#111827]">{r.machine}</td>
                    <td className="px-4 py-3 text-slate-500">{r.type}</td>
                    <td className="px-4 py-3 text-slate-500">{r.technician}</td>
                    <td className={`px-4 py-3 font-mono ${isOverdue ? "text-[#EF4444] font-medium" : "text-slate-500"}`}>{r.nextDueDate || "—"}{isOverdue && " (overdue)"}</td>
                    <td className="px-4 py-3 text-right font-mono">{money(r.cost)}</td>
                  </tr>
                );
              })}
              {!loading && rows.length === 0 && <tr><td colSpan={5}><EmptyState icon={Wrench} title="No maintenance logged yet" hint="Track preventive and corrective maintenance per machine here." actionLabel="Log Maintenance" onAction={() => setShowForm(true)} /></td></tr>}
            </tbody>
          </table>
        </div>
      </div>
      {showForm && <MaintenanceFormPanel onClose={() => setShowForm(false)} onSubmit={addRecord} saving={savingMaintenance} />}
    </div>
  );
}

function MaintenanceFormPanel({ onClose, onSubmit, saving = false }) {
  const [form, setForm] = useState({ machine: machinesSeed[0]?.name || "", type: MAINTENANCE_TYPES[0], technician: "", cost: "", notes: "", nextDueDate: "" });
  function set(key, val) { setForm((f) => ({ ...f, [key]: val })); }
  function handleSubmit(e) { e.preventDefault(); if (!form.machine.trim() || !form.technician.trim()) return; onSubmit(form); }

  return (
    <div className="fixed inset-0 z-30 flex justify-end">
      <div className="absolute inset-0 bg-[#111827]/20 backdrop-blur-[2px]" onClick={onClose} />
      <form onSubmit={handleSubmit} className="relative w-full sm:w-[400px] bg-white h-full rounded-l-[26px] border-l border-slate-200/80 shadow-2xl overflow-y-auto flex flex-col" style={{ animation: "slideIn .15s ease-out" }}>
        <div className="px-5 sm:px-6 pt-5 sm:pt-6 pb-4 sm:pb-5 border-b border-slate-100 bg-white/95 backdrop-blur sticky top-0 z-10 flex items-start justify-between">
          <div><p className="text-[11px] text-slate-400 uppercase tracking-wide">Maintenance</p><h2 className="text-[18px] font-semibold text-[#111827] mt-0.5">Log Maintenance</h2></div>
          <button type="button" onClick={onClose} className="text-slate-400 hover:text-slate-600" aria-label="Close"><X size={18} /></button>
        </div>
        <div className="px-5 sm:px-6 py-5 flex-1 space-y-4">
          <FormField label="Machine" required><input className={inputClass} value={form.machine} onChange={(e) => set("machine", e.target.value)} placeholder="e.g. Powder Coat Booth" /></FormField>
          <div className="grid grid-cols-2 gap-3">
            <FormField label="Type">
              <select className={inputClass} value={form.type} onChange={(e) => set("type", e.target.value)}>
                {MAINTENANCE_TYPES.map((t) => <option key={t} value={t}>{t}</option>)}
              </select>
            </FormField>
            <FormField label="Technician" required><input className={inputClass} value={form.technician} onChange={(e) => set("technician", e.target.value)} placeholder="e.g. S. Kileo" /></FormField>
          </div>
          <div className="grid grid-cols-2 gap-3">
            <FormField label="Cost (TZS 000)"><input type="number" min="0" className={inputClass} value={form.cost} onChange={(e) => set("cost", e.target.value)} placeholder="0" /></FormField>
            <FormField label="Next due date"><input type="date" className={inputClass} value={form.nextDueDate} onChange={(e) => set("nextDueDate", e.target.value)} /></FormField>
          </div>
          <FormField label="Notes"><textarea className={inputClass} rows={2} value={form.notes} onChange={(e) => set("notes", e.target.value)} /></FormField>
          <p className="text-[11.5px] text-slate-400">A non-zero cost creates a real "Maintenance" expense in Finance automatically.</p>
        </div>
        <div className="px-5 sm:px-6 py-4 border-t border-slate-100 bg-white/95 backdrop-blur sticky bottom-0 z-10 flex gap-2">
          <button type="button" onClick={onClose} className="flex-1 text-[12px] font-medium border border-slate-200 rounded-lg py-2.5 hover:bg-slate-50">Cancel</button>
          <button type="submit" disabled={saving} aria-busy={saving} className="flex-1 text-[12px] font-medium btn-primary text-white rounded-lg py-2.5 disabled:cursor-not-allowed disabled:opacity-60">{saving ? "Saving…" : "Log Maintenance"}</button>
        </div>
      </form>
    </div>
  );
}

/* ------------------------------- SUPPLY CHAIN ---------------------------------- */

const SCM_TABS = [
  { id: "shipments", label: "Shipments", icon: Truck },
  { id: "fleet", label: "Fleet", icon: ClipboardList },
];

function SupplyChain() {
  const [tab, setTab] = useState("shipments");
  const [savingVehicleReg, setSavingVehicleReg] = useState(null);
  const shipments = useCompanyTable("scm_shipments", shipmentsSeed, { order: { col: "dispatch_date", ascending: false }, mapRow: mapShipmentRow });
  const vehicles = useCompanyTable("scm_vehicles", vehiclesSeed, { order: { col: "reg", ascending: true }, mapRow: mapVehicleRow });

  const stats = useMemo(() => {
    const active = shipments.rows.filter((s) => s.status !== "Delivered").length;
    const inTransit = shipments.rows.filter((s) => s.status === "In Transit").length;
    const delivered = shipments.rows.filter((s) => s.status === "Delivered").length;
    const availableVehicles = vehicles.rows.filter((v) => v.status === "Available").length;
    return { active, inTransit, delivered, availableVehicles, fleetSize: vehicles.rows.length };
  }, [shipments.rows, vehicles.rows]);

  const SCM_KPIS = [
    { label: "Active Shipments", value: String(stats.active), delta: "Not yet delivered", up: true, icon: Truck },
    { label: "In Transit", value: String(stats.inTransit), delta: "On the road", up: true, icon: Clock },
    { label: "Delivered", value: String(stats.delivered), delta: "All time", up: true, icon: CheckCircle2 },
    { label: "Fleet Available", value: `${stats.availableVehicles}/${stats.fleetSize}`, delta: "Vehicles ready", up: stats.availableVehicles > 0, icon: ClipboardList },
  ];

  // The cross-entity consequence: dispatching a shipment puts its assigned
  // vehicle On Route; delivering it frees the vehicle again.
  async function setVehicleStatus(reg, status) {
    if (!reg || savingVehicleReg === reg) return false;
    setSavingVehicleReg(reg);
    try {
      if (!IS_CONFIGURED) {
        vehicles.setRows((prev) => prev.map((v) => (v.reg === reg ? { ...v, status } : v)));
        return true;
      }
      const { data, error } = await runCompanyTableMutation("scm_vehicles", "update", { status }, { matchCol: "reg", matchVal: reg });
      if (error || !data?.id) throw error || new Error("The server did not return the updated vehicle.");
      const confirmed = mapVehicleRow(data);
      vehicles.setRows((prev) => prev.map((v) => (v.reg === reg ? confirmed : v)));
      return true;
    } catch (error) {
      notify(`Vehicle ${reg} was not updated. ${error?.message || "The shipment remains available for retry."}`, "error");
      return false;
    } finally {
      setSavingVehicleReg(null);
    }
  }

  return (
    <div className="space-y-5">
      {IS_CONFIGURED && (shipments.error || vehicles.error) && (
        <div className="bg-[#EF4444]/5 border border-[#EF4444]/20 text-[#EF4444] text-[12.5px] rounded-lg px-3.5 py-2.5">
          {"Could not reach Supabase — check your connection."}
        </div>
      )}
      <div>
        <h1 className="text-[20px] sm:text-[22px] font-semibold text-[#111827] tracking-tight">Supply Chain</h1>
        <p className="text-[13px] text-slate-500 mt-1">Deliveries and the fleet that carries them</p>
      </div>

      <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1 overflow-x-auto w-fit max-w-full">
        {SCM_TABS.map((t) => {
          const Icon = t.icon;
          const isActive = tab === t.id;
          return (
            <button
              key={t.id}
              onClick={() => setTab(t.id)}
              className={`text-[12px] font-medium px-3 py-1.5 rounded-md flex items-center gap-1.5 whitespace-nowrap transition-colors ${
                isActive ? "bg-white text-[#111827] shadow-sm" : "text-slate-500 hover:text-slate-700"
              }`}
            >
              <Icon size={13} /> {t.label}
            </button>
          );
        })}
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
        {SCM_KPIS.map((k) => <KpiCard key={k.label} item={k} />)}
      </div>

      {/* Delivery analytics */}
      {shipments.rows.length > 0 && (
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-4">
          {/* Delivery status PieChart */}
          <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4">
            <h3 className="text-[13.5px] font-semibold text-[#111827] mb-3">Shipment Status</h3>
            {(() => {
              const STATUS_CFG = {Delivered:"#16A34A","In Transit":"#F59E0B",Dispatched:"#3B82F6",Pending:"#94A3B8"};
              const sdata = Object.entries(
                shipments.rows.reduce((m,s)=>({...m,[s.status]:(m[s.status]||0)+1}),{})
              ).map(([name,value])=>({name,value,fill:STATUS_CFG[name]||"#6B7280"}));
              const onTime   = shipments.rows.filter(s=>s.status==="Delivered").length;
              const onTimeRate = shipments.rows.length > 0 ? Math.round(onTime/shipments.rows.length*100) : 0;
              return (
                <div className="flex items-center gap-4">
                  <ResponsiveContainer width="55%" height={130}>
                    <RPieChart>
                      <Pie data={sdata} dataKey="value" cx="50%" cy="50%" outerRadius={55} innerRadius={32}>
                        {sdata.map((d,i)=><Cell key={i} fill={d.fill}/>)}
                      </Pie>
                      <Tooltip formatter={(v,n)=>[v+" shipments",n]}/>
                    </RPieChart>
                  </ResponsiveContainer>
                  <div className="flex-1 space-y-2">
                    {sdata.map(d=>(
                      <div key={d.name} className="flex items-center justify-between">
                        <span className="flex items-center gap-1.5 text-[12px] text-slate-600">
                          <span className="w-2.5 h-2.5 rounded-full" style={{background:d.fill}}/>
                          {d.name}
                        </span>
                        <span className="text-[13px] font-bold" style={{color:d.fill}}>{d.value}</span>
                      </div>
                    ))}
                    <div className="pt-2 border-t border-slate-100">
                      <p className="text-[11.5px] text-slate-500">Delivery rate: <strong style={{color:"#16A34A"}}>{onTimeRate}%</strong></p>
                    </div>
                  </div>
                </div>
              );
            })()}
          </div>

          {/* Weekly shipment BarChart */}
          <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm p-4">
            <h3 className="text-[13.5px] font-semibold text-[#111827] mb-3">Shipments — Last 6 Months</h3>
            {(() => {
              const months = Array.from({length:6},(_,i)=>{
                const d = new Date(TODAY.getFullYear(),TODAY.getMonth()-5+i,1);
                const key = d.toISOString().slice(0,7);
                const ms = shipments.rows.filter(s=>(s.dispatchDate||"").startsWith(key));
                return {
                  month:d.toLocaleString("default",{month:"short"}),
                  delivered:ms.filter(s=>s.status==="Delivered").length,
                  inTransit:ms.filter(s=>s.status!=="Delivered").length,
                };
              });
              return (
                <ResponsiveContainer width="100%" height={130}>
                  <BarChart data={months} margin={{left:-10,right:4,top:0,bottom:0}}>
                    <CartesianGrid vertical={false} stroke="#F3F4F6"/>
                    <XAxis dataKey="month" tick={{fontSize:10}} axisLine={false} tickLine={false}/>
                    <YAxis tick={{fontSize:9}} axisLine={false} tickLine={false}/>
                    <Tooltip/>
                    <Bar dataKey="delivered"  stackId="a" fill="#16A34A" radius={[0,0,0,0]} name="Delivered"/>
                    <Bar dataKey="inTransit"  stackId="a" fill="#F59E0B" radius={[3,3,0,0]} name="In Transit"/>
                  </BarChart>
                </ResponsiveContainer>
              );
            })()}
          </div>
        </div>
      )}

      {tab === "shipments" && <Shipments shipments={shipments} vehicles={vehicles} onVehicleStatus={setVehicleStatus} vehicleSaving={savingVehicleReg} />}
      {tab === "fleet" && <Fleet vehicles={vehicles} />}
    </div>
  );
}

function Shipments({ shipments, vehicles, onVehicleStatus, vehicleSaving = null }) {
  const [query, setQuery] = useState("");
  const [selected, setSelected] = useState(null);
  const [showForm, setShowForm] = useState(false);
  const [savingShipment, setSavingShipment] = useState(false);
  const [advancingShipmentId, setAdvancingShipmentId] = useState(null);
  const [deletingShipmentId, setDeletingShipmentId] = useState(null);
  const { rows, setRows, loading } = shipments;

  const filtered = useMemo(() => {
    if (!query.trim()) return rows;
    const q = query.toLowerCase();
    return rows.filter((s) => s.customer.toLowerCase().includes(q) || s.id.toLowerCase().includes(q) || s.destination.toLowerCase().includes(q));
  }, [rows, query]);

  async function addShipment(form) {
    if (savingShipment) return;
    const draft = {
      id: docId("DL"),
      orderRef: form.orderRef || "—",
      customer: form.customer,
      destination: form.destination,
      vehicle: form.vehicle || null,
      dispatchDate: form.dispatchDate,
      expectedDate: form.expectedDate,
      status: "Preparing",
    };
    setSavingShipment(true);
    try {
      if (!IS_CONFIGURED) {
        setRows((prev) => [draft, ...prev]);
        setShowForm(false);
        notify(`Shipment ${draft.id} created for ${draft.customer}`);
        return;
      }
      const { data, error } = await runCompanyTableMutation("scm_shipments", "insert", {
        order_ref: draft.orderRef, customer: draft.customer, destination: draft.destination,
        vehicle_reg: draft.vehicle, dispatch_date: draft.dispatchDate, expected_date: draft.expectedDate, status: "Preparing",
      });
      if (error || !data?.id) throw error || new Error("The server did not return the shipment.");
      const confirmed = mapShipmentRow(data);
      setRows((prev) => [confirmed, ...prev]);
      setShowForm(false);
      notify(`Shipment ${confirmed.id} created for ${confirmed.customer}`);
    } catch (error) {
      notify(`Shipment was not created. ${error?.message || "Your form is still available to retry."}`, "error");
    } finally {
      setSavingShipment(false);
    }
  }

  async function advanceShipment(id, next) {
    if (advancingShipmentId || deletingShipmentId) return false;
    const shp = rows.find((s) => s.id === id);
    if (!shp) return false;
    setAdvancingShipmentId(id);
    try {
      let confirmed = { ...shp, status: next };
      if (IS_CONFIGURED && shp.dbId) {
        const { data, error } = await runCompanyTableMutation("scm_shipments", "update", { status: next }, { matchVal: shp.dbId });
        if (error || !data?.id) throw error || new Error("The server did not return the updated shipment.");
        confirmed = mapShipmentRow(data);
      }
      setRows((prev) => prev.map((s) => (s.id === id ? confirmed : s)));
      setSelected((s) => (s && s.id === id ? confirmed : s));
      if (shp.vehicle) {
        const vehicleStatus = next === "Dispatched" ? "On Route" : next === "Delivered" ? "Available" : null;
        if (vehicleStatus) {
          const vehicleSaved = await onVehicleStatus(shp.vehicle, vehicleStatus);
          if (!vehicleSaved) notify("Shipment status is confirmed, but the linked vehicle needs reconciliation.", "error");
        }
      }
      if (next === "Delivered") notify(id + " delivered" + (shp.vehicle ? " — " + shp.vehicle + " is available again" : ""));
      return true;
    } catch (error) {
      notify(`Shipment status was not changed. ${error?.message || "Try again."}`, "error");
      return false;
    } finally {
      setAdvancingShipmentId(null);
    }
  }

  async function deleteShipment(id) {
    if (deletingShipmentId || advancingShipmentId) return false;
    const shp = rows.find((s) => s.id === id);
    if (!shp) return false;
    setDeletingShipmentId(id);
    try {
      if (IS_CONFIGURED && shp.dbId) {
        const { error } = await runCompanyTableMutation("scm_shipments", "delete", null, { matchVal: shp.dbId });
        if (error) throw error;
      }
      setRows((prev) => prev.filter((s) => s.id !== id));
      setSelected(null);
      notify(`Shipment ${id} deleted.`);
      return true;
    } catch (error) {
      notify(`Shipment was not deleted. ${error?.message || "Try again."}`, "error");
      return false;
    } finally {
      setDeletingShipmentId(null);
    }
  }

  return (
    <div className="space-y-5">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
        <div className="relative w-full sm:w-72">
          <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
          <input
            value={query}
            onChange={(e) => setQuery(e.target.value)}
            placeholder="Search shipments, customers, destinations..."
            className="w-full bg-white border border-slate-200 rounded-lg pl-8 pr-3 py-2 text-[13px] outline-none focus:border-[#16A34A] focus:ring-1 focus:ring-[#16A34A]/30 transition-all"
          />
        </div>
        <button
          onClick={() => setShowForm(true)}
          className="btn-primary text-white text-[13px] font-medium px-3.5 py-2 rounded-lg flex items-center justify-center gap-1.5 shadow-sm shrink-0"
        >
          <Plus size={15} /> New Shipment
        </button>
      </div>

      <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-[13px] min-w-[760px]">
            <thead>
              <tr className="border-b border-slate-100 text-left text-[11px] text-slate-400 uppercase tracking-wide">
                <th className="px-4 py-3 font-medium">Shipment</th>
                <th className="px-4 py-3 font-medium">Customer</th>
                <th className="px-4 py-3 font-medium">Destination</th>
                <th className="px-4 py-3 font-medium">Vehicle</th>
                <th className="px-4 py-3 font-medium">Expected</th>
                <th className="px-4 py-3 font-medium">Status</th>
                <th className="px-4 py-3"></th>
              </tr>
            </thead>
            <tbody>
              {loading && <SkeletonRows cols={7} />}
              {!loading && filtered.map((s) => (
                <tr
                  key={s.id}
                  onClick={() => setSelected(s)}
                  className="border-b border-slate-50 last:border-0 hover:bg-slate-50/70 cursor-pointer transition-colors"
                >
                  <td className="px-4 py-3">
                    <p className="font-mono font-medium text-[#111827]">{s.id}</p>
                    <p className="text-[11px] text-slate-400 font-mono">{s.orderRef}</p>
                  </td>
                  <td className="px-4 py-3 text-slate-700">{s.customer}</td>
                  <td className="px-4 py-3 text-slate-500">{s.destination}</td>
                  <td className="px-4 py-3 font-mono text-slate-500">{s.vehicle || "—"}</td>
                  <td className="px-4 py-3 font-mono text-slate-500">{s.expectedDate}</td>
                  <td className="px-4 py-3">
                    <span
                      className="text-[11px] font-medium px-2 py-1 rounded-full inline-flex items-center gap-1.5"
                      style={{ backgroundColor: `${SHIPMENT_STATUS_COLOR[s.status]}14`, color: SHIPMENT_STATUS_COLOR[s.status] }}
                    >
                      <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: SHIPMENT_STATUS_COLOR[s.status] }} />
                      {s.status}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-right"><ChevronRight size={15} className="text-slate-300 inline" /></td>
                </tr>
              ))}
              {!loading && filtered.length === 0 && rows.length > 0 && (
                <tr><td colSpan={7} className="px-4 py-10 text-center text-slate-400 text-[13px]">No shipments match "{query}"</td></tr>
              )}
              {!loading && rows.length === 0 && (
                <tr>
                  <td colSpan={7}>
                    <EmptyState
                      icon={Truck}
                      title="No shipments yet"
                      hint="Create a delivery for a fulfilled order. Dispatching it will put the assigned vehicle On Route automatically."
                      actionLabel="New Shipment"
                      onAction={() => setShowForm(true)}
                    />
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {selected && (
        <ShipmentPanel shipment={selected} onClose={() => setSelected(null)} onAdvance={advanceShipment} onDelete={deleteShipment} advancing={advancingShipmentId === selected.id} deleting={deletingShipmentId === selected.id} vehicleSaving={Boolean(vehicleSaving && selected.vehicle === vehicleSaving)} />
      )}
      {showForm && <ShipmentFormPanel vehicles={vehicles.rows} onClose={() => setShowForm(false)} onSubmit={addShipment} saving={savingShipment} />}
    </div>
  );
}

function ShipmentPanel({ shipment, onClose, onAdvance, onDelete, advancing = false, deleting = false, vehicleSaving = false }) {
  const nextStatus = SHIPMENT_STATUS_NEXT[shipment.status];
  return (
    <div className="fixed inset-0 z-30 flex justify-end">
      <div className="absolute inset-0 bg-[#111827]/20 backdrop-blur-[2px]" onClick={onClose} />
      <div className="relative w-full sm:w-[400px] bg-white h-full rounded-l-[26px] border-l border-slate-200/80 shadow-2xl p-6 overflow-y-auto flex flex-col" style={{ animation: "slideIn .15s ease-out" }}>
        <div className="flex items-start justify-between mb-6">
          <div>
            <p className="text-[11px] font-mono text-slate-400">{shipment.id} · {shipment.orderRef}</p>
            <h2 className="text-[18px] font-semibold text-[#111827] mt-0.5">{shipment.customer}</h2>
            <p className="text-[13px] text-slate-500">{shipment.destination}</p>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600" aria-label="Close"><X size={18} /></button>
        </div>

        <div className="mb-6">
          <span
            className="text-[11px] font-medium px-2 py-1 rounded-full inline-flex items-center gap-1.5"
            style={{ backgroundColor: `${SHIPMENT_STATUS_COLOR[shipment.status]}14`, color: SHIPMENT_STATUS_COLOR[shipment.status] }}
          >
            <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: SHIPMENT_STATUS_COLOR[shipment.status] }} />
            {shipment.status}
          </span>
        </div>

        <div className="grid grid-cols-2 gap-3 mb-6">
          <div className="bg-slate-50 rounded-lg p-3">
            <p className="text-[11px] text-slate-400 mb-1">Dispatch</p>
            <p className="text-[15px] font-mono font-semibold text-[#111827]">{shipment.dispatchDate}</p>
          </div>
          <div className="bg-slate-50 rounded-lg p-3">
            <p className="text-[11px] text-slate-400 mb-1">Expected</p>
            <p className="text-[15px] font-mono font-semibold text-[#111827]">{shipment.expectedDate}</p>
          </div>
        </div>

        <div className="flex items-center gap-2.5 text-[13px] text-slate-600 mb-6">
          <Truck size={14} className="text-slate-400" /> {shipment.vehicle ? `Assigned to ${shipment.vehicle}` : "No vehicle assigned yet"}
        </div>

        <div className="flex-1" />

        <div className="border-t border-slate-100 pt-4 flex flex-col gap-2">
          {nextStatus && (
            <button
              onClick={() => onAdvance(shipment.id, nextStatus)}
              disabled={advancing || deleting || vehicleSaving}
              aria-busy={advancing || vehicleSaving}
              className="btn-primary text-white text-[12px] font-medium rounded-lg py-2.5 disabled:cursor-not-allowed disabled:opacity-60"
            >
              {advancing || vehicleSaving ? "Saving…" : `Mark ${nextStatus}`}
            </button>
          )}
          <ConfirmDeleteButton label={deleting ? "Deleting…" : "Delete shipment"} busy={deleting} disabled={deleting || advancing || vehicleSaving} onConfirm={() => onDelete(shipment.id)} />
        </div>
      </div>
    </div>
  );
}

function ShipmentFormPanel({ vehicles, onClose, onSubmit, saving = false }) {
  const [form, setForm] = useState({
    customer: "", orderRef: "", destination: "", vehicle: "",
    dispatchDate: TODAY.toISOString().slice(0, 10), expectedDate: "",
  });
  const [touched, setTouched] = useState(false);
  const valid = form.customer.trim() && form.destination.trim() && form.expectedDate;
  const available = vehicles.filter((v) => v.status === "Available");

  function set(key, val) { setForm((f) => ({ ...f, [key]: val })); }
  function handleSubmit(e) {
    e.preventDefault();
    setTouched(true);
    if (!valid) return;
    onSubmit(form);
  }

  return (
    <div className="fixed inset-0 z-30 flex justify-end">
      <div className="absolute inset-0 bg-[#111827]/20 backdrop-blur-[2px]" onClick={onClose} />
      <form onSubmit={handleSubmit} className="relative w-full sm:w-[420px] bg-white h-full rounded-l-[26px] border-l border-slate-200/80 shadow-2xl overflow-y-auto flex flex-col" style={{ animation: "slideIn .15s ease-out" }}>
        <div className="px-5 sm:px-6 pt-5 sm:pt-6 pb-4 sm:pb-5 border-b border-slate-100 bg-white/95 backdrop-blur sticky top-0 z-10 flex items-start justify-between">
          <div>
            <p className="text-[11px] text-slate-400 uppercase tracking-wide">Supply Chain</p>
            <h2 className="text-[18px] font-semibold text-[#111827] mt-0.5">New Shipment</h2>
          </div>
          <button type="button" onClick={onClose} className="text-slate-400 hover:text-slate-600" aria-label="Close"><X size={18} /></button>
        </div>

        <div className="px-5 sm:px-6 py-5 flex-1 space-y-4">
          <FormField label="Customer" required>
            <input className={inputClass} value={form.customer} onChange={(e) => set("customer", e.target.value)} placeholder="e.g. Meridian Logistics" />
            {touched && !form.customer.trim() && <p className="text-[11px] text-[#EF4444] mt-1">Customer is required.</p>}
          </FormField>

          <div className="grid grid-cols-2 gap-3">
            <FormField label="Order reference">
              <input className={inputClass} value={form.orderRef} onChange={(e) => set("orderRef", e.target.value)} placeholder="e.g. SO-2117" />
            </FormField>
            <FormField label="Vehicle">
              <select className={inputClass} value={form.vehicle} onChange={(e) => set("vehicle", e.target.value)}>
                <option value="">Assign later</option>
                {available.map((v) => <option key={v.reg} value={v.reg}>{v.reg} — {v.type}</option>)}
              </select>
            </FormField>
          </div>

          <FormField label="Destination" required>
            <input className={inputClass} value={form.destination} onChange={(e) => set("destination", e.target.value)} placeholder="e.g. Dar es Salaam — Kurasini" />
            {touched && !form.destination.trim() && <p className="text-[11px] text-[#EF4444] mt-1">Destination is required.</p>}
          </FormField>

          <div className="grid grid-cols-2 gap-3">
            <FormField label="Dispatch date">
              <input type="date" className={inputClass} value={form.dispatchDate} onChange={(e) => set("dispatchDate", e.target.value)} />
            </FormField>
            <FormField label="Expected delivery" required>
              <input type="date" className={inputClass} value={form.expectedDate} onChange={(e) => set("expectedDate", e.target.value)} />
              {touched && !form.expectedDate && <p className="text-[11px] text-[#EF4444] mt-1">Expected date is required.</p>}
            </FormField>
          </div>

          <p className="text-[11.5px] text-slate-400">
            Only vehicles currently marked <span className="font-medium text-slate-500">Available</span> can be assigned. Dispatching moves the vehicle On Route.
          </p>
        </div>

        <div className="px-5 sm:px-6 py-4 border-t border-slate-100 bg-white/95 backdrop-blur sticky bottom-0 z-10 flex gap-2">
          <button type="button" onClick={onClose} className="flex-1 text-[12px] font-medium border border-slate-200 rounded-lg py-2.5 hover:bg-slate-50 transition-colors">Cancel</button>
          <button type="submit" disabled={saving} aria-busy={saving} className="flex-1 btn-primary text-white text-[12px] font-medium rounded-lg py-2.5 disabled:cursor-not-allowed disabled:opacity-60">{saving ? "Creating…" : "Create Shipment"}</button>
        </div>
      </form>
    </div>
  );
}

function Fleet({ vehicles }) {
  const { rows, setRows, loading } = vehicles;

  async function setStatus(reg, status) {
    setRows((prev) => prev.map((v) => (v.reg === reg ? { ...v, status } : v)));
    if (IS_CONFIGURED) {
      try { await sb("scm_vehicles").eq("reg", reg).update({ status }).run(); } catch (_e) { notify("Vehicle status saved locally, but the server update failed.", "error"); }
    }
  }

  return (
    <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full text-[13px] min-w-[680px]">
          <thead>
            <tr className="border-b border-slate-100 text-left text-[11px] text-slate-400 uppercase tracking-wide">
              <th className="px-4 py-3 font-medium">Vehicle</th>
              <th className="px-4 py-3 font-medium">Driver</th>
              <th className="px-4 py-3 font-medium">Capacity</th>
              <th className="px-4 py-3 font-medium">Status</th>
              <th className="px-4 py-3 font-medium text-right">Action</th>
            </tr>
          </thead>
          <tbody>
            {loading && <SkeletonRows cols={5} />}
            {!loading && rows.length === 0 && (
              <tr>
                <td colSpan={5}>
                  <EmptyState icon={Truck} title="No vehicles registered" hint="Your delivery fleet will appear here once vehicles are added." />
                </td>
              </tr>
            )}
            {!loading && rows.map((v) => (
              <tr key={v.reg} className="border-b border-slate-50 last:border-0">
                <td className="px-4 py-3">
                  <p className="font-mono font-medium text-[#111827]">{v.reg}</p>
                  <p className="text-[11px] text-slate-400">{v.type}</p>
                </td>
                <td className="px-4 py-3 text-slate-500">{v.driver}</td>
                <td className="px-4 py-3 font-mono text-slate-500">{v.capacity}</td>
                <td className="px-4 py-3">
                  <span
                    className="text-[11px] font-medium px-2 py-1 rounded-full inline-flex items-center gap-1.5"
                    style={{ backgroundColor: `${VEHICLE_STATUS_COLOR[v.status]}14`, color: VEHICLE_STATUS_COLOR[v.status] }}
                  >
                    <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: VEHICLE_STATUS_COLOR[v.status] }} />
                    {v.status}
                  </span>
                </td>
                <td className="px-4 py-3 text-right">
                  <div className="flex gap-1.5 justify-end">
                    {v.status !== "Available" && (
                      <button onClick={() => setStatus(v.reg, "Available")} className="text-[11.5px] font-medium border border-slate-200 rounded-md px-2.5 py-1 hover:bg-slate-50 text-slate-600">
                        Set Available
                      </button>
                    )}
                    {v.status !== "Maintenance" && (
                      <button onClick={() => setStatus(v.reg, "Maintenance")} className="text-[11.5px] font-medium border border-[#F59E0B]/30 text-[#8a670a] rounded-md px-2.5 py-1 hover:bg-[#F59E0B]/5">
                        Maintenance
                      </button>
                    )}
                  </div>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

/* --------------------------------- E-COMMERCE ----------------------------------- */

const ECOM_TABS = [
  { id: "storefront", label: "Storefront", icon: Store },
  { id: "orders", label: "Orders", icon: ShoppingCart },
];

function CommerceCapabilityPanel({ onNavigate }) {
  const capabilities = [
    { label: "Catalog & stock", detail: "Published products reconcile to ERP inventory rows.", state: "Connected", icon: Package, action: "Review inventory", target: "inventory" },
    { label: "Orders & finance", detail: "Order status can advance only through confirmed records.", state: "Connected", icon: ReceiptText, action: "Review sales", target: "sales" },
    { label: "Customer records", detail: "Customer identity remains in the confirmed CRM/sales ledger.", state: "Connected", icon: Users, action: "Open CRM", target: "crm" },
    { label: "Checkout & payments", detail: "Requires an approved cart, payment, and server RPC contract.", state: "Contract gated", icon: CreditCard },
    { label: "Shipping & returns", detail: "No E-Commerce-specific shipping or return contract is exposed yet.", state: "Contract gated", icon: Truck },
    { label: "Reviews & promotions", detail: "No confirmed review, coupon, or storefront promotion source is available.", state: "Contract gated", icon: Tag },
  ];
  return <section className="sm-panel rounded-xl bg-white p-4 sm:p-5" aria-label="Commerce capability coverage">
    <div className="flex flex-col gap-1 sm:flex-row sm:items-end sm:justify-between"><div><h2 className="text-[14px] font-semibold text-[#111827]">Commerce capability coverage</h2><p className="text-[11px] text-slate-500">Connected workflows are actionable; contract-gated features are intentionally not simulated.</p></div><span className="text-[10px] text-slate-400">Source: live ERP contracts</span></div>
    <div className="mt-4 grid grid-cols-1 gap-2 sm:grid-cols-2 xl:grid-cols-3">{capabilities.map((item) => { const Icon = item.icon; const connected = item.state === "Connected"; return <div key={item.label} className="flex min-h-[104px] items-start gap-3 rounded-lg border border-slate-200 bg-slate-50/60 p-3"><span className={`grid h-8 w-8 shrink-0 place-items-center rounded-lg ${connected ? "bg-emerald-50 text-emerald-700" : "bg-amber-50 text-amber-700"}`}><Icon size={15} /></span><div className="min-w-0 flex-1"><div className="flex items-start justify-between gap-2"><p className="text-[11.5px] font-semibold text-slate-800">{item.label}</p><span className={`shrink-0 text-[9px] font-bold uppercase tracking-[.08em] ${connected ? "text-emerald-700" : "text-amber-700"}`}>{item.state}</span></div><p className="mt-1 text-[10.5px] leading-4 text-slate-500">{item.detail}</p>{item.target && <button type="button" onClick={() => onNavigate?.(item.target)} className="mt-2 min-h-11 text-[10px] font-bold text-emerald-700 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-600">{item.action} <ChevronRight size={11} className="inline" /></button>}</div></div>; })}</div>
  </section>;
}

function ECommerce({ inventory, onNavigate }) {
  const [tab, setTab] = useState("storefront");
  const products = useCompanyTable("ecommerce_products", storefrontSeed, {
    select: "*,inventory_items(name,category)", order: { col: "sku", ascending: true }, mapRow: mapProductRow,
  });
  const orders = useCompanyTable("ecommerce_orders", onlineOrdersSeed, {
    select: "*,ecommerce_order_items(*)", order: { col: "order_date", ascending: false }, mapRow: mapOnlineOrderRow,
  });

  const stats = useMemo(() => {
    const allOrders = orders.rows;
    const live = allOrders.filter((o) => o.status !== "Cancelled");
    const revenue = live.reduce((s, o) => s + o.total, 0);
    const published = products.rows.filter((p) => p.published).length;
    const statusCount = (status) => allOrders.filter((o) => o.status === status).length;
    const lowStock = inventory.rows.filter((item) => Number(item.qty) <= Number(item.reorder || item.reorderLevel || 0) && Number(item.reorder || item.reorderLevel || 0) > 0).length;
    const valuedRows = inventory.rows.filter((item) => Number.isFinite(Number(item.unitCost)) && Number(item.unitCost) >= 0);
    const inventoryValue = valuedRows.reduce((s, item) => s + (Number(item.qty) || 0) * (Number(item.unitCost) || 0), 0);
    return {
      revenue, count: live.length,
      avg: live.length ? Math.round(revenue / live.length) : 0,
      published, total: products.rows.length,
      pending: statusCount("Payment Pending") + statusCount("Pending"),
      processing: statusCount("Processing"), shipped: statusCount("Shipped"), delivered: statusCount("Delivered"),
      cancelled: statusCount("Cancelled"), lowStock,
      inventoryValue: valuedRows.length ? inventoryValue : null,
    };
  }, [orders.rows, products.rows, inventory.rows]);

  const ECOM_KPIS = [
    { label: "Online Revenue", value: `TZS ${money(stats.revenue)}k`, delta: "Confirmed non-cancelled orders", up: true, icon: CircleDollarSign },
    { label: "Orders", value: String(stats.count), delta: `${stats.cancelled} cancelled excluded`, up: true, icon: ShoppingCart },
    { label: "Avg Order Value", value: stats.count ? `TZS ${money(stats.avg)}k` : "Insufficient confirmed data", delta: "Confirmed orders only", up: true, icon: Percent },
    { label: "Published Products", value: `${stats.published}/${stats.total}`, delta: "Live against confirmed catalog rows", up: true, icon: Globe },
    { label: "Pending Payment", value: String(stats.pending), delta: "Needs payment confirmation", up: false, icon: Clock3 },
    { label: "Processing", value: String(stats.processing), delta: "Awaiting fulfillment", up: true, icon: Package },
    { label: "Low Stock", value: String(stats.lowStock), delta: "Inventory reorder signals", up: false, icon: AlertTriangle },
    { label: "Inventory Value", value: stats.inventoryValue === null ? "Insufficient confirmed data" : `TZS ${money(stats.inventoryValue)}k`, delta: "Uses unit cost where confirmed", up: true, icon: WalletCards },
  ];

  return (
    <div className="space-y-5">
      <div>
        <h1 className="text-[20px] sm:text-[22px] font-semibold text-[#111827] tracking-tight">E-Commerce</h1>
        <p className="text-[13px] text-slate-500 mt-1">Your online storefront, priced from live Inventory stock</p>
      </div>

      <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1 overflow-x-auto w-fit max-w-full">
        {ECOM_TABS.map((t) => {
          const Icon = t.icon;
          const isActive = tab === t.id;
          return (
            <button
              key={t.id}
              onClick={() => setTab(t.id)}
              className={`text-[12px] font-medium px-3 py-1.5 rounded-md flex items-center gap-1.5 whitespace-nowrap transition-colors ${
                isActive ? "bg-white text-[#111827] shadow-sm" : "text-slate-500 hover:text-slate-700"
              }`}
            >
              <Icon size={13} /> {t.label}
            </button>
          );
        })}
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4">
        {ECOM_KPIS.map((k) => <KpiCard key={k.label} item={k} />)}
      </div>
      <p className="text-[10px] text-slate-400">Source: confirmed ecommerce orders, ecommerce products, and ERP inventory rows. Payment, conversion, customer, coupon, shipping, and attribution metrics remain unavailable until their server-confirmed contracts exist.</p>
      <CommerceCapabilityPanel onNavigate={onNavigate} />

      {tab === "storefront" && <Storefront products={products} inventory={inventory} />}
      {tab === "orders" && <OnlineOrders orders={orders} />}
    </div>
  );
}

function Storefront({ products, inventory }) {
  const [view, setView] = useState("grid");
  const [category, setCategory] = useState("all");
  const [stockFilter, setStockFilter] = useState("all");
  const [sortBy, setSortBy] = useState("relevance");
  const [query, setQuery] = useState("");
  const { rows, setRows, loading } = products;

  const categories = useMemo(() => [...new Set(rows.map((p) => p.category))], [rows]);

  const filtered = useMemo(() => {
    const matching = rows.filter((p) => {
      const stockItem = inventory.rows.find((it) => it.sku === p.sku);
      const stockState = stockItem ? stockStatus(stockItem.qty, stockItem.reorder || stockItem.reorderLevel || 0) : "Unavailable";
      const matchesCat = category === "all" || p.category === category;
      const matchesQ = !query.trim() || `${p.name} ${p.sku} ${p.category}`.toLowerCase().includes(query.toLowerCase());
      const matchesStock = stockFilter === "all" || (stockFilter === "available" && ["In Stock", "Low Stock"].includes(stockState)) || (stockFilter === "low" && stockState === "Low Stock") || (stockFilter === "out" && stockState === "Out of Stock");
      return matchesCat && matchesQ && matchesStock;
    });
    return [...matching].sort((a, b) => sortBy === "price-low" ? a.price - b.price : sortBy === "price-high" ? b.price - a.price : sortBy === "newest" ? String(b.sku).localeCompare(String(a.sku)) : String(a.name).localeCompare(String(b.name)));
  }, [rows, inventory.rows, category, stockFilter, sortBy, query]);

  async function togglePublished(sku) {
    setRows((prev) => prev.map((p) => (p.sku === sku ? { ...p, published: !p.published } : p)));
    if (IS_CONFIGURED) {
      try {
        const p = rows.find((x) => x.sku === sku);
        await sb("ecommerce_products").eq("sku", sku).update({ published: !p.published }).run();
      } catch (_e) { notify("Couldn't save the publish state to the server.", "error"); }
    }
  }

  return (
    <div className="space-y-4">
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-3">
        <div className="flex items-center gap-1 bg-slate-100 rounded-lg p-1 overflow-x-auto">
          <button
            onClick={() => setCategory("all")}
            className={`text-[12px] font-medium px-3 py-1.5 rounded-md whitespace-nowrap transition-colors ${category === "all" ? "bg-white text-[#111827] shadow-sm" : "text-slate-500"}`}
          >
            All categories
          </button>
          {categories.map((c) => (
            <button
              key={c}
              onClick={() => setCategory(c)}
              className={`text-[12px] font-medium px-3 py-1.5 rounded-md whitespace-nowrap transition-colors ${category === c ? "bg-white text-[#111827] shadow-sm" : "text-slate-500"}`}
            >
              {c}
            </button>
          ))}
        </div>
        <div className="flex gap-2">
          <div className="relative flex-1 sm:w-56">
            <Search size={14} className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" />
            <input
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              placeholder="Search products or SKU..."
              aria-label="Search products or SKU"
              className="w-full bg-white border border-slate-200 rounded-lg pl-8 pr-3 py-2 text-[13px] outline-none focus:border-[#16A34A] focus:ring-1 focus:ring-[#16A34A]/30 transition-all"
            />
          </div>
          <select value={stockFilter} onChange={(e) => setStockFilter(e.target.value)} aria-label="Filter products by stock" className="min-h-11 rounded-lg border border-slate-200 bg-white px-2.5 text-[11px] text-slate-600 outline-none focus:border-[#16A34A] focus:ring-1 focus:ring-[#16A34A]/30">
            <option value="all">All stock</option>
            <option value="available">Available</option>
            <option value="low">Low stock</option>
            <option value="out">Out of stock</option>
          </select>
          <select value={sortBy} onChange={(e) => setSortBy(e.target.value)} aria-label="Sort products" className="min-h-11 rounded-lg border border-slate-200 bg-white px-2.5 text-[11px] text-slate-600 outline-none focus:border-[#16A34A] focus:ring-1 focus:ring-[#16A34A]/30">
            <option value="relevance">Sort: relevance</option>
            <option value="newest">Newest/SKU</option>
            <option value="price-low">Price low to high</option>
            <option value="price-high">Price high to low</option>
          </select>
          <div className="flex items-center gap-0.5 bg-slate-100 rounded-lg p-1 shrink-0">
            <button type="button" onClick={() => setView("grid")} aria-label="Grid view" aria-pressed={view === "grid"} className={`min-h-11 min-w-11 p-1.5 rounded-md ${view === "grid" ? "bg-white shadow-sm text-[#111827]" : "text-slate-400"}`}>
              <Grid3x3 size={15} />
            </button>
            <button type="button" onClick={() => setView("list")} aria-label="List view" aria-pressed={view === "list"} className={`min-h-11 min-w-11 p-1.5 rounded-md ${view === "list" ? "bg-white shadow-sm text-[#111827]" : "text-slate-400"}`}>
              <List size={15} />
            </button>
          </div>
        </div>
      </div>

      {loading ? (
        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4">
          {Array.from({ length: 8 }).map((_, i) => (
            <div key={i} className="rounded-xl border border-slate-200/80 overflow-hidden">
              <div className="h-28 skeleton-shimmer" />
              <div className="p-3 space-y-2">
                <div className="h-3 rounded skeleton-shimmer w-3/4" />
                <div className="h-3 rounded skeleton-shimmer w-1/2" />
              </div>
            </div>
          ))}
        </div>
      ) : filtered.length === 0 ? (
        <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm">
          <EmptyState icon={Store} title="No products found" hint="Try a different search or category filter." />
        </div>
      ) : view === "grid" ? (
        <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4">
          {filtered.map((p) => {
            const stockItem = inventory.rows.find((it) => it.sku === p.sku);
            const status = stockItem ? stockStatus(stockItem.qty, stockItem.reorder) : null;
            return (
              <div
                key={p.sku}
                className="sm-panel rounded-xl overflow-hidden bg-white hover:-translate-y-0.5 transition-all duration-200"
              >
                <div
                  className="h-28 relative flex items-center justify-center"
                  style={{ background: CATEGORY_GRADIENT[p.category] || "linear-gradient(135deg, #111827, #16A34A)" }}
                >
                  <div className="flex flex-col items-center gap-1 text-white/85"><Package size={30} strokeWidth={1.5} /><span className="text-[9px] font-semibold uppercase tracking-[.1em]">Image not configured</span></div>
                  {p.featured && (
                    <span className="absolute top-2 left-2 flex items-center gap-1 text-[10px] font-semibold text-[#111827] bg-white/95 rounded-full px-2 py-0.5">
                      <Star size={9} fill="#F59E0B" className="text-[#F59E0B]" /> Featured
                    </span>
                  )}
                  <span
                    className={`absolute top-2 right-2 text-[10px] font-semibold rounded-full px-2 py-0.5 ${p.published ? "bg-white/95 text-[#16A34A]" : "bg-black/40 text-white"}`}
                  >
                    {p.published ? "Live" : "Draft"}
                  </span>
                </div>
                <div className="p-3.5">
                  <p className="text-[10.5px] text-slate-400 uppercase tracking-wide">{p.category}</p>
                  <p className="text-[13px] font-medium text-[#111827] leading-snug mt-0.5 mb-2 line-clamp-2 min-h-[32px]">{p.name}</p>
                  <div className="flex items-center justify-between mb-2.5">
                    <span className="text-[14px] font-mono font-semibold text-[#111827]">TZS {money(p.price)}k</span>
                    {status && (
                      <span
                        className="text-[10px] font-medium px-1.5 py-0.5 rounded"
                        style={{ backgroundColor: `${STOCK_STATUS_COLOR[status]}14`, color: STOCK_STATUS_COLOR[status] }}
                      >
                        {status}
                      </span>
                    )}
                  </div>
                  <button
                    type="button"
                    onClick={() => togglePublished(p.sku)}
                    aria-pressed={p.published}
                    className={`w-full min-h-11 text-[11.5px] font-medium rounded-lg py-1.5 transition-colors ${
                      p.published ? "border border-slate-200 text-slate-500 hover:bg-slate-50" : "btn-primary text-white"
                    }`}
                  >
                    {p.published ? "Unpublish" : "Publish"}
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      ) : (
        <div className="bg-white rounded-xl border border-slate-200/80 shadow-sm overflow-hidden">
          <div className="overflow-x-auto">
            <table className="w-full text-[13px] min-w-[600px]">
              <thead>
                <tr className="border-b border-slate-100 text-left text-[11px] text-slate-400 uppercase tracking-wide">
                  <th className="px-4 py-3 font-medium">Product</th>
                  <th className="px-4 py-3 font-medium">Category</th>
                  <th className="px-4 py-3 font-medium text-right">Price</th>
                  <th className="px-4 py-3 font-medium">Status</th>
                  <th className="px-4 py-3"></th>
                </tr>
              </thead>
              <tbody>
                {filtered.map((p) => (
                  <tr key={p.sku} className="border-b border-slate-50 last:border-0">
                    <td className="px-4 py-3">
                      <div className="flex items-center gap-2.5">
                          <div className="w-8 h-8 rounded-lg shrink-0 flex items-center justify-center" style={{ background: CATEGORY_GRADIENT[p.category] }} title="Product image not configured">
                            <Package size={14} className="text-white/85" />
                          </div>
                        <div>
                          <p className="font-medium text-[#111827]">{p.name}</p>
                          {p.featured && <p className="text-[10.5px] text-[#F59E0B] flex items-center gap-1"><Star size={9} fill="#F59E0B" /> Featured</p>}
                        </div>
                      </div>
                    </td>
                    <td className="px-4 py-3 text-slate-500">{p.category}</td>
                    <td className="px-4 py-3 text-right font-mono">{money(p.price)}</td>
                    <td className="px-4 py-3">
                      <span className={`text-[11px] font-medium px-2 py-1 rounded-full ${p.published ? "bg-[#16A34A]/10 text-[#16A34A]" : "bg-slate-100 text-slate-500"}`}>
                        {p.published ? "Live" : "Draft"}
                      </span>
                    </td>
                    <td className="px-4 py-3 text-right">
                      <button onClick={() => togglePublished(p.sku)} className="text-[11.5px] font-medium text-[#16A34A] hover:text-[#15803D]">
                        {p.published ? "Unpublish" : "Publish"}
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      )}
    </div>
  );
}

function OnlineOrders({ orders }) {
  const [selected, setSelected] = useState(null);
  const [query, setQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState("all");
  const { rows, setRows, loading } = orders;
  const filteredRows = useMemo(() => rows.filter((order) => {
    const matchesQuery = !query.trim() || `${order.id} ${order.customer || ""} ${order.email || ""}`.toLowerCase().includes(query.toLowerCase());
    const matchesStatus = statusFilter === "all" || order.status === statusFilter;
    return matchesQuery && matchesStatus;
  }), [rows, query, statusFilter]);

  async function advanceOrder(id, next) {
    const order = rows.find((o) => o.id === id);
    setRows((prev) => prev.map((o) => (o.id === id ? { ...o, status: next } : o)));
    setSelected((s) => (s && s.id === id ? { ...s, status: next } : s));
    notify(`${id} marked ${next}`);
    if (IS_CONFIGURED && order?.dbId) {
      try { await sb("ecommerce_orders").eq("id", order.dbId).update({ status: next }).run(); } catch (_e) { notify("Couldn't save the order status to the server.", "error"); }
    }
  }

  const nextStatus = { "Payment Pending": "Processing", Processing: "Shipped", Shipped: "Delivered", Delivered: null, Cancelled: null };

  return (
    <div className="space-y-4" aria-label="E-Commerce order management">
      <div className="flex flex-col gap-2 sm:flex-row sm:items-center sm:justify-between">
        <div><h2 className="text-[15px] font-semibold text-[#111827]">Order execution</h2><p className="text-[11px] text-slate-500">Review confirmed orders and advance only through supported server states.</p></div>
        <div className="flex flex-col gap-2 sm:flex-row">
          <input value={query} onChange={(e) => setQuery(e.target.value)} placeholder="Search order or customer..." aria-label="Search orders" className="min-h-11 rounded-lg border border-slate-200 bg-white px-3 text-[11px] outline-none focus:border-[#16A34A] focus:ring-1 focus:ring-[#16A34A]/30" />
          <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} aria-label="Filter orders by status" className="min-h-11 rounded-lg border border-slate-200 bg-white px-3 text-[11px] text-slate-600 outline-none focus:border-[#16A34A] focus:ring-1 focus:ring-[#16A34A]/30"><option value="all">All statuses</option>{[...new Set(rows.map((order) => order.status).filter(Boolean))].map((status) => <option key={status} value={status}>{status}</option>)}</select>
        </div>
      </div>
      <div className="grid grid-cols-1 lg:grid-cols-3 gap-5">
      <div className="sm-panel lg:col-span-2 bg-white rounded-xl overflow-hidden">
        <div className="overflow-x-auto">
          <table className="w-full text-[13px] min-w-[600px]">
            <thead>
              <tr className="border-b border-slate-100 text-left text-[11px] text-slate-400 uppercase tracking-wide">
                <th className="px-4 py-3 font-medium">Order</th>
                <th className="px-4 py-3 font-medium">Customer</th>
                <th className="px-4 py-3 font-medium text-right">Total</th>
                <th className="px-4 py-3 font-medium">Status</th>
                <th className="px-4 py-3"></th>
              </tr>
            </thead>
            <tbody>
              {loading && <SkeletonRows cols={5} />}
              {!loading && filteredRows.length === 0 && <tr><td colSpan={5} className="px-4 py-10 text-center text-[11px] text-slate-400">{rows.length ? "No orders match the current search and status filter." : "No confirmed orders yet."}</td></tr>}
              {!loading && filteredRows.map((o) => (
                <tr key={o.id} onClick={() => setSelected(o)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); setSelected(o); } }} tabIndex={0} role="button" aria-label={`Open order ${o.id}`} className="border-b border-slate-50 last:border-0 hover:bg-slate-50/70 cursor-pointer transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-emerald-600">
                  <td className="px-4 py-3 font-mono font-medium text-[#111827]">{o.id}</td>
                  <td className="px-4 py-3">
                    <p className="text-slate-700">{o.customer}</p>
                    <p className="text-[11px] text-slate-400">{o.email}</p>
                  </td>
                  <td className="px-4 py-3 text-right font-mono">{money(o.total)}</td>
                  <td className="px-4 py-3">
                    <span
                      className="text-[11px] font-medium px-2 py-1 rounded-full inline-flex items-center gap-1.5"
                      style={{ backgroundColor: `${ECOM_ORDER_STATUS_COLOR[o.status]}14`, color: ECOM_ORDER_STATUS_COLOR[o.status] }}
                    >
                      <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: ECOM_ORDER_STATUS_COLOR[o.status] }} />
                      {o.status}
                    </span>
                  </td>
                  <td className="px-4 py-3 text-right"><ChevronRight size={15} className="text-slate-300 inline" /></td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>

      <div className="sm-panel bg-white rounded-xl p-4 sm:p-5">
        <h3 className="text-[14px] font-semibold text-[#111827] mb-1">Orders This Week</h3>
        <p className="text-[11.5px] text-slate-400 mb-3">Daily order volume</p>
        <ResponsiveContainer width="100%" height={180}>
          <BarChart data={STOREFRONT_TREND} margin={{ top: 5, right: 0, left: -24, bottom: 0 }}>
            <CartesianGrid vertical={false} stroke="#EEF1F4" />
            <XAxis dataKey="d" tick={{ fontSize: 11, fill: "#94A3B8" }} axisLine={false} tickLine={false} />
            <YAxis tick={{ fontSize: 11, fill: "#94A3B8" }} axisLine={false} tickLine={false} allowDecimals={false} />
            <Tooltip contentStyle={{ borderRadius: 10, border: "1px solid #EEF1F4", fontSize: 12, fontFamily: "monospace" }} />
            <Bar dataKey="orders" radius={[5, 5, 0, 0]} fill="#16A34A" />
          </BarChart>
        </ResponsiveContainer>
      </div>

      {selected && (
        <OnlineOrderPanel order={selected} onClose={() => setSelected(null)} onAdvance={advanceOrder} nextStatus={nextStatus[selected.status]} />
      )}
      </div>
    </div>
  );
}

function OnlineOrderPanel({ order, onClose, onAdvance, nextStatus }) {
  return (
    <div className="fixed inset-0 z-30 flex justify-end" role="dialog" aria-modal="true" aria-labelledby="online-order-panel-title">
      <button type="button" className="absolute inset-0 bg-[#111827]/20 backdrop-blur-[2px] cursor-default" onClick={onClose} aria-label="Close order details" />
      <div className="relative w-full sm:w-[400px] bg-white h-full rounded-l-[26px] border-l border-slate-200/80 shadow-2xl p-6 overflow-y-auto flex flex-col" style={{ animation: "slideIn .15s ease-out" }}>
        <div className="flex items-start justify-between mb-6">
          <div>
            <p className="text-[11px] font-mono text-slate-400">{order.id}</p>
            <h2 id="online-order-panel-title" className="text-[18px] font-semibold text-[#111827] mt-0.5">{order.customer}</h2>
            <p className="text-[13px] text-slate-500">{order.email}</p>
          </div>
          <button type="button" onClick={onClose} className="min-h-11 min-w-11 grid place-items-center rounded-lg text-slate-400 hover:bg-slate-50 hover:text-slate-600 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-600" aria-label="Close order details"><X size={18} /></button>
        </div>

        <div className="mb-6">
          <span
            className="text-[11px] font-medium px-2 py-1 rounded-full inline-flex items-center gap-1.5"
            style={{ backgroundColor: `${ECOM_ORDER_STATUS_COLOR[order.status]}14`, color: ECOM_ORDER_STATUS_COLOR[order.status] }}
          >
            <span className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: ECOM_ORDER_STATUS_COLOR[order.status] }} />
            {order.status}
          </span>
        </div>
        <section aria-label="Order status timeline" className="mb-6">
          <h3 className="text-[11px] font-bold uppercase tracking-[.12em] text-slate-400">Timeline</h3>
          <ol className="mt-3 space-y-2 border-l border-slate-200 pl-4">
            {["Payment Pending", "Processing", "Shipped", "Delivered"].map((status) => {
              const currentIndex = ["Payment Pending", "Processing", "Shipped", "Delivered"].indexOf(order.status);
              const stepIndex = ["Payment Pending", "Processing", "Shipped", "Delivered"].indexOf(status);
              const reached = order.status === "Cancelled" ? false : currentIndex >= stepIndex;
              return <li key={status} className={`relative text-[11px] ${reached ? "font-semibold text-emerald-700" : "text-slate-400"}`}><span className={`absolute -left-[21px] top-0.5 h-2.5 w-2.5 rounded-full border-2 border-white ${reached ? "bg-emerald-600" : "bg-slate-300"}`} aria-hidden="true" />{status}</li>;
            })}
          </ol>
          <p className="mt-2 text-[10px] text-slate-400">Timeline reflects only statuses confirmed by the current order contract.</p>
        </section>

        <div className="border border-slate-100 rounded-lg overflow-hidden mb-5">
          {order.items.map((it, i) => (
            <div key={i} className={`flex items-center justify-between px-3 py-2.5 text-[13px] ${i !== order.items.length - 1 ? "border-b border-slate-50" : ""}`}>
              <div>
                <p className="text-slate-700">{it.name}</p>
                <p className="text-[11px] text-slate-400 font-mono">{it.qty} × TZS {money(it.price)}k</p>
              </div>
              <span className="font-mono text-[#111827]">{money(it.qty * it.price)}k</span>
            </div>
          ))}
        </div>

        <div className="flex justify-between text-[14px] font-semibold text-[#111827] mb-6">
          <span>Total</span>
          <span className="font-mono">TZS {money(order.total)}k</span>
        </div>

        <div className="flex items-center gap-2.5 text-[13px] text-slate-600 mb-6">
          <CreditCard size={14} className="text-slate-400" /> Paid via {order.method}
        </div>

        <div className="flex-1" />

        {nextStatus && (
          <button type="button" onClick={() => onAdvance(order.id, nextStatus)} className="btn-primary min-h-11 text-white text-[12px] font-medium rounded-lg py-2.5 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-emerald-600 focus-visible:ring-offset-2">
            Mark {nextStatus}
          </button>
        )}
      </div>
    </div>
  );
}

/* --------------------------------- REPORTS ------------------------------------ */

// RFC-4180-style CSV export: quotes fields containing commas, quotes, or
// newlines, and doubles embedded quotes. Downloads via a Blob object URL.
function exportCSV(filename, headers, rows) {
  const esc = (v) => {
    const s = String(v ?? "");
    return /[",\n]/.test(s) ? `"${s.replace(/"/g, '""')}"` : s;
  };
  const csv = [headers, ...rows].map((r) => r.map(esc).join(",")).join("\n");
  const blob = new Blob([csv], { type: "text/csv;charset=utf-8" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
  notify(`Exported ${filename}`);
}

// Real .xlsx via SheetJS — an actual spreadsheet file, not a renamed CSV.
function exportExcel(filename, sheetName, headers, rows) {
  const worksheet = XLSX.utils.aoa_to_sheet([headers, ...rows]);
  const workbook = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(workbook, worksheet, sheetName.slice(0, 31)); // Excel's own 31-char sheet name limit
  XLSX.writeFile(workbook, filename);
  notify(`Exported ${filename}`);
}

// Word recognizes HTML wrapped in its own XML namespace when given a
// .doc extension — no docx-generation library exists in this environment
// (mammoth, the one library available, only reads .docx, it does not write
// one). This is a real, longstanding browser technique, not a renamed
// text file: opening the result in Word shows genuine formatting, not raw
// markup.
function exportWord(filename, title, bodyHtml) {
  const html = `<html xmlns:o='urn:schemas-microsoft-com:office:office' xmlns:w='urn:schemas-microsoft-com:office:word' xmlns='http://www.w3.org/TR/REC-html40'>
    <head><meta charset="utf-8"><title>${title}</title>
    <style>
      body { font-family: Calibri, Arial, sans-serif; font-size: 11pt; color: #111827; }
      h1 { font-size: 18pt; color: #111827; } h2 { font-size: 13pt; color: #16A34A; margin-top: 18pt; }
      table { border-collapse: collapse; width: 100%; margin-top: 8pt; }
      th, td { border: 1px solid #DEE2E6; padding: 6px 10px; font-size: 10pt; text-align: left; }
      th { background: #F5F7FA; font-weight: 600; }
      .right { text-align: right; }
    </style></head>
    <body>${bodyHtml}</body></html>`;
  const blob = new Blob(['\ufeff', html], { type: "application/msword" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
  notify(`Exported ${filename}`);
}

// Real PDF via the browser's own print-to-PDF, not a bundled PDF library
// (none is available in this environment). Opens a clean, print-formatted
// window and calls window.print() — every modern browser's print dialog
// offers "Save as PDF" natively, so this genuinely produces a PDF without
// pretending to have PDF-generation code this build does not have.
function printAsPDF(title, bodyHtml, opts) {
  const o = opts || {};
  const accent = o.accent || "#16A34A";
  const companyName = o.companyName || "";
  const logo = o.logo || "";
  const headerRight = o.headerRight || ("Generated: " + new Date().toLocaleDateString());
  const win = window.open("", "_blank", "width=900,height=1100");
  if (!win) { notify("Pop-up blocked — allow pop-ups to export PDF.", "error"); return; }
  win.document.write(
    '<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"/>' +
    '<title>' + title + '</title>' +
    '<link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet"/>' +
    '<style>' +
    '*{box-sizing:border-box;margin:0;padding:0}' +
    'body{font-family:Inter,Arial,sans-serif;color:#111827;background:#fff;-webkit-print-color-adjust:exact;print-color-adjust:exact}' +
    '.doc{max-width:820px;margin:0 auto;padding:40px 48px 56px}' +
    '.doc-hdr{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:36px;padding-bottom:20px;border-bottom:3px solid ' + accent + '}' +
    '.brand{font-size:22px;font-weight:800;color:#111827}.brand-sub{font-size:11px;color:#6B7280;margin-top:3px}' +
    '.doc-title{font-size:28px;font-weight:900;color:' + accent + ';text-align:right;letter-spacing:-0.5px}' +
    '.doc-meta{text-align:right;margin-top:4px;font-size:11px;color:#6B7280;line-height:1.7}' +
    'h2{font-size:10.5px;font-weight:700;color:' + accent + ';text-transform:uppercase;letter-spacing:.1em;margin:28px 0 10px;padding-bottom:5px;border-bottom:1px solid #E5E7EB}' +
    'p{font-size:12.5px;color:#374151;line-height:1.6;margin-bottom:6px}' +
    'table{border-collapse:collapse;width:100%;margin-top:8px;font-size:11.5px}' +
    'thead tr{background:' + accent + ';color:#fff}' +
    'thead th{padding:10px 12px;text-align:left;font-weight:600;font-size:10.5px;text-transform:uppercase;letter-spacing:.06em}' +
    'tbody tr{border-bottom:1px solid #F3F4F6}' +
    'tbody tr:nth-child(even){background:#FAFAFA}' +
    'tbody td{padding:9px 12px;color:#374151;font-size:12px}' +
    '.right{text-align:right!important}.center{text-align:center}' +
    '.total-row td{font-weight:700;background:#F0FDF4!important;border-top:2px solid ' + accent + ';font-size:13px}' +
    '.summary{background:' + accent + '0D;border:1px solid ' + accent + '30;border-radius:10px;padding:20px 24px;margin-top:24px}' +
    '.sum-row{display:flex;justify-content:space-between;padding:5px 0;font-size:12.5px;border-bottom:1px solid ' + accent + '18}' +
    '.sum-row:last-child{border:none;font-weight:800;font-size:14.5px;margin-top:6px;padding-top:10px}' +
    '.badge{display:inline-block;padding:2px 9px;border-radius:20px;font-size:10px;font-weight:700}' +
    '.b-paid{background:#DCFCE7;color:#15803D}.b-partial{background:#FEF3C7;color:#92400E}.b-unpaid{background:#FEE2E2;color:#991B1B}.b-active{background:#DBEAFE;color:#1E40AF}' +
    '.footer{margin-top:48px;padding-top:14px;border-top:1px solid #E5E7EB;text-align:center;font-size:10px;color:#9CA3AF;line-height:1.6}' +
    '.print-btn{position:fixed;bottom:24px;right:24px;display:flex;gap:8px;z-index:9}' +
    '.print-btn button{padding:10px 20px;border:none;border-radius:8px;font-weight:600;cursor:pointer;font-family:Inter,sans-serif;font-size:13px}' +
    '@media print{@page{margin:16mm 12mm;size:A4}.print-btn{display:none!important}.doc{padding:0}}' +
    '</style></head><body>' +
    '<div class="doc">' +
    '<div class="doc-hdr">' +
    '<div>' + (logo ? '<img src="' + logo + '" style="height:44px;object-fit:contain;margin-bottom:8px;display:block"/>' : '') +
    '<div class="brand">' + (companyName || "BusinessSphere ERP") + '</div>' +
    '<div class="brand-sub">BusinessSphere ERP · Enterprise Resource Planning</div></div>' +
    '<div><div class="doc-title">' + title + '</div><div class="doc-meta">' + headerRight + '</div></div>' +
    '</div>' +
    bodyHtml +
    '<div class="footer">Powered by BusinessSphere ERP · Generated ' + new Date().toLocaleString() + ' · Computer-generated document — no signature required</div>' +
    '</div>' +
    '<div class="print-btn">' +
    '<button onclick="window.print()" style="background:' + accent + ';color:#fff">🖨 Print / PDF</button>' +
    '<button onclick="window.close()" style="background:#F3F4F6;color:#374151">✕ Close</button>' +
    '</div>' +
    '<script>setTimeout(function(){window.print()},600)<\/script>' +
    '</body></html>'
  );
  win.document.close();
  win.focus();
}

// Real configuration, honestly limited execution: this defines what a
