function LoginPage({ onAuthenticated, onSwitchToSignup, onForgotPassword, onOAuth, initialDiagnostic = null }) {
  const [identifier, setIdentifier] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(null);
  const [tiltX, setTiltX] = useState(0);
  const [tiltY, setTiltY] = useState(0);

  async function handleSubmit(e) {
    e.preventDefault();
    const validationError = validatePasswordLogin(identifier, password);
    if (validationError) { setError(validationError); return; }
    setBusy(true); setError(null);
    try {
      if (!IS_CONFIGURED) {
        const configError = new Error("Authentication is not configured.");
        configError.code = "AUTH_CONFIGURATION_MISSING";
        throw configError;
      }
      const result = await authSignIn(identifier.trim(), password);
      persistAuthSession(result);
      authDebug("Authentication completed");
      window.location.reload();
    } catch (loginError) { setError(toAuthUserMessage(loginError)); }
    finally { setBusy(false); }
  }

  function handleMouseMove(e) {
    const r = e.currentTarget.getBoundingClientRect();
    setTiltX(-((e.clientY - r.top - r.height / 2) / (r.height / 2)) * 7);
    setTiltY(((e.clientX - r.left - r.width / 2) / (r.width / 2)) * 7);
  }

  return <EnterpriseLoginView
    configured={IS_CONFIGURED}
    onSignup={onSwitchToSignup}
    onForgot={onForgotPassword}
    onOAuth={onOAuth}
    onPasskey={async (remember) => {
      try {
        const result = await signInWithAccountPasskey({ supabaseUrl: SUPABASE_URL, supabaseAnonKey: SUPABASE_ANON_KEY });
        persistAuthSession(result, { remember });
        window.location.reload();
      } catch (passkeyError) {
        const error = new Error(passkeySignInUserMessage(passkeyError));
        error.code = passkeyError?.code;
        throw error;
      }
    }}
    toMessage={toAuthUserMessage}
    terminalDiagnostic={initialDiagnostic}
    onSignIn={async (email, submittedPassword) => {
      if (!IS_CONFIGURED) {
        const configError = new Error("Authentication is not configured.");
        configError.code = "AUTH_CONFIGURATION_MISSING";
        throw configError;
      }
      const result = await authSignIn(email, submittedPassword);
      persistAuthSession(result);
      authDebug("Authentication completed");
      window.location.reload();
    }}
  />;
}

